function r(band,subject,key,topic,concept,meaning,why,rule,intuition,qa,extra={}) {
 const [example,error,compare,validate,apply,extend]=qa;
 const defaults={papers:['qres-consort'],models:['qres-google'],product:['qres-exp'],information:['qres-shannon']};
 return {band,subject,key,topic,concept,meaning,why,rule,intuition,example,error,compare,validate,apply,extend,formula:'',prerequisites:[],checks:[],sourceIds:defaults[subject],...extra};
}

const skills = [
 // Band 1: asking and measuring simple questions.
 r(1,'papers','paper-question','Reading research','A testable research question',
 'A question that names what will be compared and what will be measured.',
 'It turns a vague claim into something evidence can answer.',
 'Specify the people, change, comparison, outcome and observation period.',
 '"Does this help?" is blurry. "Does a reminder increase paid renewals versus no reminder?" is measurable.',[
 ['Turn "our app is better" into a testable question.','Does the new app reduce task time for new users compared with the old app?'],
 ['A study asks whether a supplement "improves health" but names no outcome. What is missing?','A defined health outcome, a comparison group and a time window.'],
 ['What is the difference between a research question and a result?','The question says what we want to learn; the result is what the collected data show.'],
 ['Before comparing two study answers, what must match in their questions?','Their populations, interventions, comparisons, outcomes and time windows must be sufficiently similar.'],
 ['A trader says a filter works. What concrete question could test this?','Does adding the filter improve net returns after fees on future trades compared with the same strategy without it?'],
 ['Why is "Does a reminder raise clicks?" different from "Does it raise renewals?"','Clicks are an intermediate action. More clicks may not produce more paid renewals.']]),
 r(1,'papers','paper-population','Reading research','Target population',
 'The whole group a study wants to learn about.',
 'It tells us who a conclusion is meant to describe.',
 'Name the target group before selecting the people to measure.',
 'To study all first-time customers, existing loyal customers are not the same group.',[
 ['A survey wants to describe every adult in a city. What is its target population?','All adults in that city, not only the adults who answer.'],
 ['A student survey is advertised as evidence about all adults. What is wrong?','Students may differ from other adults in age, income and behavior.'],
 ['How does a target population differ from the measured sample?','The population is the group of interest; the sample is the subset actually measured.'],
 ['A study of mobile buyers is applied to desktop buyers. What should you check?','Whether device users differ in ways that change the result.'],
 ['A broker surveys only profitable clients. Can it describe all its clients?','Not reliably. It excludes losing and inactive clients from the measured group.'],
 ['A treatment helps healthy young volunteers. What limits use of this result?','Older or less healthy patients may respond differently; they need relevant evidence.']],{prerequisites:['paper-question']}),
 r(1,'papers','paper-sample','Reading research','A measured sample',
 'The people or observations actually collected for a study.',
 'Every numerical claim starts with knowing what was measured.',
 'Record sample size and how observations entered the sample.',
 'Tasting ten spoonfuls from one corner of a pot may miss what is elsewhere.',[
 ['A shop has 1,000 customers and interviews 100. What fraction is sampled?','100 / 1,000 = 10%.'],
 ['A report says "80% agree" without saying how many answered. What is missing?','The sample size and selection method; 4 of 5 and 800 of 1,000 carry different uncertainty.'],
 ['Which is the sample: 50 surveyed users or all 5,000 users?','The 50 surveyed users. The 5,000 users are the intended population.'],
 ['Before trusting a large sample, what selection issue should be checked?','Whether the sample systematically excludes relevant people. Large size does not repair biased selection.'],
 ['Only 20 of 200 invited customers reply. What is the response rate?','20 / 200 = 10%; the views of the missing 90% may differ.'],
 ['Is a random sample of 500 automatically less biased than 50,000 volunteers?','It may be more representative. Selection quality and sample size solve different problems.']],{prerequisites:['paper-population'],checks:[{expression:'100/1000*100',value:10},{expression:'20/200*100',value:10}]}),
 r(1,'papers','paper-comparison','Reading research','A comparison group',
 'A group or condition used as a reference for judging another result.',
 'It helps separate a change from what might have happened anyway.',
 'Compare similar groups measured in the same way over the same period.',
 'A new shop sign may appear to help during a holiday even if every shop gets busier.',[
 ['Sales rise after a new sign. What comparison would help test the sign?','Similar shops without the new sign during the same period.'],
 ['A treatment group improves, so the treatment must work. What is missing?','How a comparable untreated group changed; recovery could occur without treatment.'],
 ['What is the difference between a comparison and a guarantee?','A comparison gives evidence about an effect; it does not guarantee the same result for every person.'],
 ['One group is measured in December and another in June. What issue arises?','Seasonal changes may explain differences instead of the intervention.'],
 ['A new checkout converts 12% and the old one 10%. What observed gap is this?','12% − 10% = 2 percentage points; uncertainty and fair allocation still matter.'],
 ['Why is comparing a trader with an unchanged strategy useful?','It helps distinguish the effect of a new rule from a market change affecting both strategies.']],{prerequisites:['paper-question'],checks:[{expression:'12-10',value:2}]}),
 r(1,'papers','paper-correlation-cause','Reading research','Association versus cause',
 'Association means two things vary together. Cause means changing one changes the other.',
 'It prevents acting on a pattern that may be driven by something else.',
 'A relationship alone does not identify what an intervention would do.',
 'Ice-cream sales and sunburn can rise together because hot weather raises both.',[
 ['Busy shops sell more umbrellas on rainy days. Does shopping cause rain?','No. Rain can increase umbrella buying; the association does not establish the proposed direction.'],
 ['People using an expensive app earn more, so buying it raises income. What is wrong?','Income may influence app choice, or another factor may affect both.'],
 ['How does prediction differ from causing an outcome?','A pattern can predict an outcome even when changing the predictor would not change that outcome.'],
 ['Before treating a correlation as causal, what alternative explanations matter?','Common causes, reverse causation, selection and measurement differences.'],
 ['A screen filter is linked with higher profits. What stronger test could help?','Randomly assign the filter in a suitable experiment, or use a credible causal design.'],
 ['Why might reducing ambulance arrivals fail to reduce emergencies?','Emergencies cause ambulance arrivals. Removing the response does not remove the cause.']],{prerequisites:['paper-comparison'],sourceIds:['qres-whatif']}),
 r(1,'models','model-input-output','Prediction basics','Model inputs and outputs',
 'A model uses known inputs to produce an estimated output.',
 'It makes the prediction task clear before choosing a method.',
 'Inputs must be available when the prediction will be made.',
 'A delivery estimate uses distance and traffic to predict minutes, like a recipe uses ingredients.',[
 ['A model predicts delivery minutes from distance. What is the input and output?','Distance is the input; predicted delivery time is the output.'],
 ['A loan model uses whether the loan later defaulted as an input. What is wrong?','The future result is unavailable at approval time; this leaks the answer.'],
 ['How does an observed output differ from a predicted output?','Observed output is what happened; predicted output is the model\u2019s estimate.'],
 ['Before using a feature in live prediction, what availability check is needed?','Confirm the feature exists and is recorded before the decision time.'],
 ['A weather model predicts 12 mm of rain but 8 mm falls. Which number is the prediction?','12 mm is the prediction; 8 mm is the observed result.'],
 ['Why should a shop define "next-month sales" before training a model?','The output definition determines what data, dates and errors the model should use.']]),
 r(1,'models','model-line-intuition','Prediction basics','A straight-line prediction',
 'A simple rule that adds the same amount to a prediction for each extra input unit.',
 'It gives a clear first model for steady relationships.',
 'Starting value + change per unit × number of units.',
 'A delivery fee can start at €3 and add €2 for each kilometer.',[
 ['A fee starts at €3 and adds €2 per kilometer. What is the predicted fee for 4 km?','€3 + €2 × 4 = €11.'],
 ['The same fee is €3 + €2 × distance. Someone predicts €20 at 4 km. What is wrong?','The rule gives €11, not €20. Multiply the per-unit charge and then add the start.'],
 ['With that fee rule, how much does 1 extra kilometer add?','€2; the starting €3 does not change the amount added per kilometer.'],
 ['Before using a straight line for bulk orders, what pattern should be checked?','Whether the per-unit change stays roughly constant; volume discounts may bend the relationship.'],
 ['A shop predicts orders as 10 + 5 × ad units. What does 2 units predict?','10 + 5 × 2 = 20 orders. This is a prediction, not proof of the ad\u2019s causal effect.'],
 ['Why can a straight-line demand model fail at very high prices?','It may predict impossible negative demand or miss a changing response outside the observed range.']],{prerequisites:['model-input-output'],formula:'prediction = start + per-unit change × input',checks:[{expression:'3+2*4',value:11},{expression:'10+5*2',value:20}]}),
 r(1,'product','product-conversion','Product basics','Conversion rate',
 'The share of eligible people who complete a chosen action.',
 'It measures actions such as buying, signing up or renewing.',
 'Conversion rate = converters / eligible people × 100%.',
 'If 5 of every 100 visitors buy, purchase conversion is 5%.',[
 ['30 of 600 eligible visitors buy. What is purchase conversion?','30 / 600 × 100% = 5%.'],
 ['A report divides buyers by page views although some visitors open many pages. What is the problem?','It measures buyers per page view, not the share of visitors who buy. Define the denominator.'],
 ['50 sales from 1,000 visitors versus 40 from 400: which has higher visitor conversion?','5% versus 10%; the second converts twice as well despite fewer sales.'],
 ['Before comparing conversion rates, what should match?','The action, eligible-user definition, measurement window and counting unit.'],
 ['An app has 80 paid upgrades among 2,000 eligible free users. What is upgrade conversion?','80 / 2,000 × 100% = 4%.'],
 ['Why can a higher signup conversion still be bad for a business?','The extra signups may retain poorly, cost more to serve or never become profitable customers.']],{formula:'conversion = converters / eligible people',checks:[{expression:'30/600*100',value:5},{expression:'50/1000*100',value:5},{expression:'40/400*100',value:10},{expression:'80/2000*100',value:4}]}),
 r(1,'information','info-surprise-intuition','Information basics','Information as surprise',
 'An unexpected event carries more information than an event you already expected.',
 'It explains why probability matters when judging news and predictions.',
 'Lower probability means greater surprise when the event actually occurs.',
 '"The sun rose" changes little; an unexpected outage may change your plans.',[
 ['Which is more surprising: an event expected 90% of the time or 10% of the time?','The 10% event, if it happens.'],
 ['A rare event is surprising, therefore it is impossible. What is wrong?','Low probability is not zero probability. Rare events can occur.'],
 ['How is surprising information different from useful information?','Surprise concerns probability; usefulness concerns whether the news changes a decision.'],
 ['Before calling an event surprising, what expectation must be stated?','The probability assigned before observing it.'],
 ['A trader expected a halt with 5% probability and one occurs. What should be reviewed?','The probability model and decision risk, while remembering that one rare outcome does not prove miscalibration.'],
 ['Why can repeated announcements of an already-known result add little information?','After the result is known, another copy usually adds no new uncertainty reduction.']]),

 // Band 2: fair experiments and interpretable first models.
 r(2,'papers','paper-randomization','Study design','Random assignment',
 'Using chance to allocate eligible participants to study groups.',
 'It reduces systematic selection differences between treatment groups.',
 'Assign before outcomes; keep allocation unpredictable and analyze the planned comparison.',
 'A coin can choose who receives a reminder, rather than a manager choosing the easiest customers.',[
 ['A study flips a fair coin for each of 200 users. How many are expected in each group?','100 per group on average; the realized counts need not be exactly equal.'],
 ['A manager assigns the healthiest people to treatment and calls it randomized. What is wrong?','Allocation depends on health, not chance, so group differences may bias the comparison.'],
 ['How does random assignment differ from random sampling?','Assignment helps compare interventions; sampling helps represent a population. Neither substitutes for the other.'],
 ['After randomization, why inspect baseline characteristics?','To understand chance imbalances and detect implementation problems, not to demand perfect equality.'],
 ['A trader chooses only calm days for a new strategy. How could this distort evaluation?','Day conditions differ from the old-strategy sample; random allocation within eligible opportunities can help.'],
 ['Why can a properly randomized result still fail to generalize?','The recruited people or operating conditions may differ from the intended target population.']],{prerequisites:['paper-comparison','paper-sample'],checks:[{expression:'200*0.5',value:100}]}),
 r(2,'papers','paper-control','Study design','A control condition',
 'The reference condition used to compare an intervention.',
 'It helps estimate what would happen without the tested change.',
 'Choose the control to answer the intended practical question.',
 'A new lesson can be compared with the old lesson, not only with doing nothing.',[
 ['A new medicine is compared with usual care. What is the control condition?','Usual care, as defined and delivered in the study.'],
 ['An app is better than no app, so it is better than the leading app. What is wrong?','The study did not compare the leading app; a weak control cannot answer that claim.'],
 ['When does a placebo comparison differ from an active comparison?','Placebo compares with an inactive look-alike; an active comparison uses another real intervention.'],
 ['If both trial groups receive different extra support, what must be checked?','Whether support differences explain the outcome rather than the intended intervention alone.'],
 ['A shop tests free shipping against its current €4 fee. What practical question is answered?','The effect of offering free shipping versus the existing fee in that setting.'],
 ['Why might an effective treatment show a smaller difference against a strong active control?','Both groups may benefit; the difference estimates the extra benefit over the active option.']],{prerequisites:['paper-randomization']}),
 r(2,'papers','paper-blinding','Study design','Blinding',
 'Keeping specified people unaware of which intervention a participant received.',
 'It can reduce expectation and assessment bias.',
 'State who is blinded: participants, providers, assessors or analysts.',
 'A judge who does not know which training group a person joined is less likely to score with expectations.',[
 ['An assessor scores pain without knowing treatment assignment. Who is blinded?','The outcome assessor; this does not imply participants or clinicians are also blinded.'],
 ['A paper says "double-blind" but gives no roles. What is unclear?','Which people were blinded and whether blinding was maintained.'],
 ['Why is blinding especially relevant for a self-rated symptom?','Expectations can change reporting even without the same change in the underlying symptom.'],
 ['A treatment has obvious side effects. What blinding issue should be checked?','Participants or assessors may infer assignment, weakening the intended protection.'],
 ['How could a coding benchmark reduce evaluator favoritism?','Hide system labels from evaluators and use predefined scoring rules.'],
 ['Does an unblinded trial automatically have no value?','No. Assess the risk of bias, outcome objectivity and other safeguards; blinding is one design feature.']],{prerequisites:['paper-control']}),
 r(2,'papers','paper-measurement','Study design','A defined outcome measure',
 'A stated rule for turning an outcome into recorded data.',
 'It prevents different groups from being scored by different standards.',
 'Use the same definition, tool and observation window across compared groups.',
 'Counting "active users" means little until "active" is defined, such as at least one completed task.',[
 ['A study defines success as completing a task in 5 minutes. What makes this measurable?','It has a specific action and time threshold.'],
 ['Treatment users report purchases while control users use verified receipts. What is wrong?','Different measurement methods can create a group difference without a real purchase difference.'],
 ['How does measurement error differ from an actual outcome difference?','Measurement error is recording the result inaccurately; an outcome difference is a real change in what happened.'],
 ['A new sensor reports 10% higher values. What should be checked before calling this a treatment effect?','Its calibration and whether both groups used the same sensor procedure.'],
 ['A return study ignores trading fees. What outcome should replace gross return for a profit question?','Net return after relevant fees, spread and slippage.'],
 ['Can a perfectly repeatable test still measure the wrong thing?','Yes. Reliability means consistent measurement; validity asks whether it measures the intended concept.']],{prerequisites:['paper-question','paper-control']}),
 r(2,'papers','paper-observation-experiment','Study design','Observation versus intervention',
 'An observational study records choices; an experiment assigns an intervention.',
 'The distinction changes how strongly group differences support causal claims.',
 'Ask who chose the exposure and what could influence that choice.',
 'Watching people choose coffee differs from randomly assigning a specified coffee dose.',[
 ['Researchers record which people already use a diet app. Is this observational or experimental?','Observational: the researchers did not assign app use.'],
 ['An observational association is called a randomized treatment effect. What is wrong?','Existing choices were observed, so random assignment did not remove selection into treatment.'],
 ['Can an observational study be useful without proving cause?','Yes. It can describe patterns, predict outcomes or support causal analysis under justified assumptions.'],
 ['Before interpreting an observational income gap, what selection issue matters?','People may choose different exposures because of ability, resources or prior opportunities.'],
 ['A platform randomly offers a discount to users. What design feature aids causal interpretation?','Chance assignment can create comparable groups before the offer.'],
 ['Why might an observational study be necessary despite an experiment being stronger for some causal questions?','Some interventions are unethical, impossible or too slow to assign; credible alternative designs are needed.']],{prerequisites:['paper-correlation-cause','paper-randomization'],sourceIds:['qres-whatif']}),
 r(2,'models','model-intercept','Linear models','Intercept',
 'A straight-line model\u2019s predicted value when the input is zero.',
 'It separates a starting level from the change associated with the input.',
 'In y = a + bx, a is the intercept.',
 'For a €3 starting taxi fee plus distance charges, the €3 is the intercept.',[
 ['For predicted cost = 7 + 2 × units, what is the intercept?','7 currency units, the model\u2019s cost prediction at zero units.'],
 ['The intercept is 7, so every unit adds 7. What is wrong?','The intercept is the starting value; the slope 2 gives the per-unit change.'],
 ['Two lines have the same slope but intercepts 3 and 8. What is their predicted gap?','8 − 3 = 5 at every input value.'],
 ['If zero input lies far outside the data, what should be checked before interpreting an intercept?','Whether prediction at zero is meaningful; the intercept may only position the fitted line.'],
 ['Predicted monthly orders = 50 + 4 × ad units. What are predicted orders with no ad units?','50 orders, according to this model; this is not automatically a causal no-ad estimate.'],
 ['Why might centering age around 40 make an intercept easier to read?','Zero centered age then means age 40, so the intercept predicts a person near the observed data.']],{prerequisites:['model-line-intuition'],formula:'y = a + bx; intercept = a',checks:[{expression:'8-3',value:5}]}),
 r(2,'models','model-slope','Linear models','Slope',
 'The model\u2019s output change for one extra input unit.',
 'It describes the size and direction of a fitted relationship.',
 'For a straight line, slope = output change / input change.',
 'A €2 increase for each kilometer is a slope of €2 per kilometer.',[
 ['Output rises from 20 to 32 when input rises from 2 to 5. What is the slope?','(32 − 20) / (5 − 2) = 4 output units per input unit.'],
 ['A negative slope means the model is broken. What is wrong?','A negative slope simply means predicted output falls as input rises.'],
 ['How does a slope of −3 differ from +3?','One predicts a 3-unit fall per input unit; the other predicts a 3-unit rise.'],
 ['A slope is reported without units. What should be checked?','The units and scaling of both input and outcome; cents versus euros change the coefficient.'],
 ['A fitted rent line adds €12 per extra square meter. What change does 5 extra square meters predict?','€12 × 5 = €60 more rent, holding the model\u2019s other conditions fixed.'],
 ['Why does an advertising slope not automatically show the effect of buying more ads?','Ad spending may rise when expected demand rises; causal interpretation needs a suitable design.']],{prerequisites:['model-intercept'],formula:'slope = Δoutput / Δinput',checks:[{expression:'(32-20)/(5-2)',value:4},{expression:'12*5',value:60}]}),
 r(2,'product','product-ab-random','Product experiments','A randomized A/B test',
 'A fair comparison in which eligible users are assigned by chance to versions A and B.',
 'It helps estimate whether a product change causes a difference in a metric.',
 'Assign a stable random unit, define metrics first and measure both versions consistently.',
 'Two doors lead to the same shop; chance chooses which sign each visitor sees.',[
 ['A test has 4,000 eligible users and plans a 50/50 split. What are the expected group sizes?','2,000 users per version, before losses or eligibility filtering.'],
 ['All new users get B and returning users get A. Why is this a poor A/B comparison?','User experience differs by group, so it can explain the outcome gap.'],
 ['What does random assignment add beyond comparing this week with last week?','It reduces systematic group differences while both versions face the same time conditions.'],
 ['One user repeatedly switches versions. What allocation issue should be checked?','The randomization unit and stable assignment; switching can contaminate exposure and measurement.'],
 ['A landing-page change is tested on random visitors. Which outcome best matches a revenue goal?','A predefined paid-purchase or net-revenue metric, not only extra clicks.'],
 ['Why can user-level randomization fail on a messaging network?','One user\u2019s treatment can change another user\u2019s experience; interference may require a different design.']],{prerequisites:['product-conversion','paper-randomization'],checks:[{expression:'4000*0.5',value:2000}]}),
 r(2,'information','info-signal-noise','Information basics','Signal versus noise',
 'Signal is a useful underlying pattern; noise is variation that can obscure it.',
 'It prevents overreacting to every small movement in a result.',
 'Look for repeatable patterns and measure uncertainty rather than treating every change as signal.',
 'A radio station is the signal; static makes it harder to hear.',[
 ['A shop gets 99, 103 and 98 orders on similar days. Must each difference reflect a business change?','No. Ordinary variation can move daily counts without a change in the underlying demand.'],
 ['Every upward tick confirms a trading edge. What is wrong?','Short movements contain noise; a repeatable net-performance pattern needs stronger evidence.'],
 ['How does more data help distinguish signal from noise?','For a stable process with appropriate dependence handling, more data can estimate the underlying pattern more precisely.'],
 ['Before averaging observations to reduce noise, what stability issue must be checked?','Whether the process changed over the measurement period; averaging different regimes can mislead.'],
 ['A conversion test rises by 0.1 percentage points but fluctuates by 0.5 points. What is the main concern?','The observed rise is small compared with uncertainty; it may be noise.'],
 ['Why can a noisy measurement still contain useful information?','Its individual readings may be imprecise while a repeatable average or pattern remains informative.']],{prerequisites:['info-surprise-intuition'],sourceIds:['qres-infotheory']})
];

skills.push(
 // Band 3: interpreting estimates, not merely headlines.
 r(3,'papers','paper-effect-size','Interpreting results','Size of a study effect',
 'The estimated amount by which compared outcomes differ.',
 'It tells us whether a claimed benefit is large enough to matter.',
 'Report the difference with units and uncertainty, not only whether a test passed a threshold.',
 'A scale reading is useful because it gives a weight, not simply the word \"heavy\".',[
 ['Average task time is 12 minutes for control and 9 for treatment. What is the observed effect?','Treatment is 3 minutes faster: 9 − 12 = −3 minutes, a 25% reduction relative to 12.'],
 ['A paper reports only p = 0.01 and claims a large benefit. What is missing?','The effect size and uncertainty; a small p-value does not tell us the benefit is large.'],
 ['How does a 1-minute improvement differ from a 10-minute improvement?','Both can be statistically detectable, but their practical sizes differ by a factor of 10.'],
 ['An effect uses \"units\" without defining the scale. What should be checked?','What one unit means and whether that change is meaningful to users or patients.'],
 ['A strategy adds 0.2% gross return but costs an extra 0.3%. What is the net effect?','0.2% − 0.3% = −0.1 percentage points of return; the gross gain is not a net benefit.'],
 ['Why should a reported average effect not be read as every person improving by that amount?','It summarizes a group difference; individual outcomes and effects can vary.']],{prerequisites:['paper-comparison','paper-measurement'],sourceIds:['qres-asa'],checks:[{expression:'9-12',value:-3},{expression:'(12-9)/12*100',value:25},{expression:'0.2-0.3',value:-0.1}]}),
 r(3,'papers','paper-absolute-relative','Interpreting results','Absolute and relative risk reduction',
 'Absolute reduction subtracts risks; relative reduction divides that subtraction by the starting risk.',
 'It reveals whether an impressive percentage represents a small or large real change.',
 'ARR = control risk − treatment risk; RRR = ARR / control risk.',
 'Cutting 2 cases per 100 to 1 case per 100 halves risk but prevents 1 case per 100.',[
 ['Risk falls from 10% to 8%. What are the absolute and relative reductions?','2 percentage points absolute; 2 / 10 × 100% = 20% relative.'],
 ['A 50% relative reduction always prevents 50 cases per 100 people. What is wrong?','The starting risk matters. From 2% to 1%, only 1 case per 100 is prevented on average.'],
 ['Compare halving a 20% risk with halving a 2% risk.','Absolute reductions are 10 and 1 percentage points, respectively, despite the same 50% relative reduction.'],
 ['Before comparing two risk reductions, what time-window check is needed?','Risks must refer to comparable observation periods; one-year and ten-year risks differ.'],
 ['Assuming causal risks fall from 4% to 3%, what is the number needed to treat?','ARR = 0.01; NNT = 1 / 0.01 = 100 over the stated period.'],
 ['Why can an odds ratio exaggerate the impression of a risk change for common outcomes?','Odds and risks differ. Translate to absolute risks with the relevant baseline risk before judging practical impact.']],{prerequisites:['paper-effect-size'],formula:'ARR = pc − pt; RRR = (pc − pt) / pc; NNT = 1 / ARR',sourceIds:['qres-meta'],checks:[{expression:'(0.1-0.08)/0.1*100',value:20},{expression:'1/(0.04-0.03)',value:100}]}),
 r(3,'papers','paper-ci-reading','Interpreting results','Reading a confidence interval',
 'A range produced by a procedure designed to cover a fixed target in a stated share of repeated studies.',
 'It shows how precisely an effect has been estimated under the method’s assumptions.',
 'For a 95% method, about 95% of intervals would cover the target across repeated valid studies.',
 'A wide searchlight covers more ground but locates an effect less precisely.',[
 ['A benefit estimate is 2 points with a 95% CI from −1 to 5. What does the range show?','The data and method leave substantial uncertainty, including harm, no effect and benefit.'],
 ['This fixed interval gives a 95% probability that the fixed effect lies inside. What is wrong?','Frequentist 95% coverage describes the repeated procedure, not a posterior probability for this fixed interval.'],
 ['Which is more precise: an interval from 1 to 3 or from −3 to 7?','Widths are 2 and 10 units; the first is narrower and more precise, assuming comparable valid methods.'],
 ['Before trusting a confidence interval, what study issue can coverage alone not fix?','Systematic bias, such as selection or confounding; nominal coverage relies on appropriate assumptions.'],
 ['A treatment effect has CI 0.1 to 0.3, while a useful effect starts at 2. What follows?','The estimate may be clearly above zero yet too small for the stated practical requirement.'],
 ['Why does a CI containing zero not prove there is no useful effect?','It may also contain useful effects. A weakly precise study can fail to rule out both benefit and no effect.']],{prerequisites:['paper-effect-size'],sourceIds:['qres-asa'],checks:[{expression:'3-1',value:2},{expression:'7-(-3)',value:10}]}),
 r(3,'papers','paper-pvalue-reading','Interpreting results','What a p-value asks',
 'Under a null model and its assumptions, the probability of a test statistic at least as extreme as observed.',
 'It helps check incompatibility with a specified model, while keeping hypothesis probabilities separate.',
 'State the null, statistic, alternative and assumptions before interpreting p.',
 'A rare score under a fair-coin model prompts questions about that model; it does not assign the coin a probability of being fair.',[
 ['A valid test gives p = 0.03. What probability does 3% describe?','Under the null and assumptions, a statistic at least as extreme as observed has probability 3%.'],
 ['p = 0.03 means a 97% chance that the treatment works. What is wrong?','It is not a probability of the hypothesis or the treatment working.'],
 ['Are p = 0.049 and p = 0.051 strong opposites?','No. Their evidence is nearly the same despite falling on different sides of 0.05.'],
 ['What should be checked if a very small p-value comes from many repeated analyses?','How analyses were selected and whether multiplicity or optional stopping was handled.'],
 ['A study has p = 0.001 but a tiny benefit. Should p alone determine adoption?','No. Consider effect size, uncertainty, costs and practical value.'],
 ['Why does a large p-value not prove the null is true?','The study may be noisy or too small to detect relevant departures from the null.']],{prerequisites:['paper-ci-reading'],sourceIds:['qres-asa']}),
 r(3,'papers','paper-practical-significance','Interpreting results','Practical significance',
 'Whether an effect is large enough to matter for a real decision.',
 'It keeps large sample sizes from making tiny improvements sound valuable.',
 'Choose a meaningful effect threshold and compare benefits, costs and uncertainty.',
 'A precisely measured extra drop of water may not fill a thirsty person’s glass.',[
 ['A website saves 1 millisecond per visit, but the feature costs €10,000 monthly. What question matters?','Whether that tiny speed gain creates enough user or business value to justify the cost.'],
 ['A significant result is automatically worth implementing. What is wrong?','Statistical detectability does not establish meaningful benefit or positive net value.'],
 ['How can a small study show an important effect without statistical significance?','The estimate may be large but imprecise; useful effects and uncertainty can coexist.'],
 ['Before calling a clinical improvement meaningful, what should be specified?','A relevant benefit threshold and the burdens, harms and measurement scale.'],
 ['A change earns €300 monthly and costs €500. What is the estimated net benefit?','€300 − €500 = −€200 per month, before considering uncertainty.'],
 ['Why is a huge sample not a cure for a biased study?','It can estimate the biased result very precisely; precision does not remove systematic error.']],{prerequisites:['paper-pvalue-reading'],sourceIds:['qres-asa'],checks:[{expression:'300-500',value:-200}]}),
 r(3,'models','model-residual','Model fitting','Residual',
 'The observed outcome minus the model’s prediction for that observation.',
 'It shows where and by how much a model misses.',
 'Residual = observed − predicted; keep outcome units.',
 'If a delivery arrives 3 minutes later than predicted, its residual is +3 minutes.',[
 ['A model predicts 8 minutes and the observed task takes 11. What is the residual?','11 − 8 = +3 minutes.'],
 ['A residual of −4 means the outcome was 4 above prediction. What is wrong?','A negative residual means observed was 4 below prediction.'],
 ['Which miss is larger in absolute size: residual −2 or +5?','The +5 residual: absolute errors are 2 and 5 outcome units.'],
 ['Residuals grow as predicted values grow. What should be checked?','Whether error variability changes with level; constant-variance assumptions may fail.'],
 ['A model overpredicts sales by 20 units each day. What residual pattern appears?','Repeated residuals near −20; investigate bias or missing structure.'],
 ['Why can average residual near zero still hide a bad model?','Large positive and negative misses can cancel, or residuals can show systematic patterns.']],{prerequisites:['model-slope'],formula:'e = y − ŷ',sourceIds:['qres-nist'],checks:[{expression:'11-8',value:3}]}),
 r(3,'models','model-least-squares','Model fitting','Least-squares fitting',
 'Choosing model coefficients to minimize the sum of squared residuals.',
 'It gives a clear rule for fitting a line to many observations.',
 'SSE = Σ(observed − predicted)²; compare candidate fits on the same data.',
 'Squaring makes large misses costly and prevents positive and negative misses from canceling.',[
 ['Two residuals are +2 and −3. What is their squared-error sum?','2² + (−3)² = 4 + 9 = 13 squared outcome units.'],
 ['Residuals +10 and −10 sum to zero, so the fit is perfect. What is wrong?','The squared-error sum is 100 + 100 = 200, not zero.'],
 ['Candidate A has SSE 20 and B has SSE 35 on the same observations. Which fits better by this rule?','A has smaller training squared error; this alone does not establish better future prediction.'],
 ['Before applying least squares with extreme outliers, what should be checked?','Whether outliers are real, errors or influential points; squared loss gives them large weight.'],
 ['Residuals change from 4 and 4 to 1 and 2. How much does SSE fall?','From 32 to 5, a reduction of 27 / 32 = 84.375%.'],
 ['Why can adding many fitted parameters reduce SSE without improving a model?','The model can fit noise in the training data; evaluate predictions on separate data.']],{prerequisites:['model-residual'],formula:'SSE = Σ(yi − ŷi)²',sourceIds:['qres-nist'],checks:[{expression:'2**2+(-3)**2',value:13},{expression:'10**2+(-10)**2',value:200},{expression:'(32-5)/32*100',value:84.375}]}),
 r(3,'product','product-lift','Product metrics','Absolute versus relative lift',
 'Absolute lift subtracts conversion rates; relative lift divides the gap by the control rate.',
 'It makes product improvements readable without inflated percentage headlines.',
 'Absolute lift = B − A; relative lift = (B − A) / A.',
 'A rise from 4% to 5% is one extra buyer per 100 visitors, not 25 extra buyers.',[
 ['Conversion moves from 4% to 5%. What are both lifts?','+1 percentage point absolute; 1 / 4 × 100% = +25% relative.'],
 ['A 25% relative lift from 4% means conversion is 29%. What is wrong?','4% × 1.25 = 5%; adding 25 percentage points confuses two measures.'],
 ['Which adds more buyers per 1,000: 2% to 3%, or 20% to 21%?','Both add 10 expected buyers; relative lifts differ: 50% versus 5%.'],
 ['Before interpreting a lift, what baseline information is needed?','The control rate, absolute gap, sample sizes and uncertainty.'],
 ['A credible +0.2 percentage-point lift applies to 50,000 visitors. How many extra conversions are expected?','0.002 × 50,000 = 100 extra conversions, if the effect transports.'],
 ['Why should an uncertain 30% lift not be treated as a known revenue increase?','The estimate can be noisy, the baseline matters and downstream value per conversion may change.']],{prerequisites:['product-ab-random','paper-absolute-relative'],formula:'relative lift = (pB − pA) / pA',checks:[{expression:'(0.05-0.04)/0.04*100',value:25},{expression:'0.002*50000',value:100}]}),
 r(3,'information','info-surprisal','Information measures','Surprisal in bits',
 'A numerical measure of how unexpected one event is under a probability model.',
 'It links probability to coding length and probabilistic prediction.',
 'I(event) = −log₂(p); p is the event’s assigned probability.',
 'An equally likely choice among 8 options requires 3 binary decisions: 3 bits.',[
 ['An event has probability 1/8. What is its surprisal?','−log₂(1/8) = 3 bits.'],
 ['A more probable event always has more surprisal. What is wrong?','Surprisal rises when probability falls; a certain event has 0 bits.'],
 ['Compare surprisal for probabilities 1/2 and 1/4.','They are 1 and 2 bits, respectively.'],
 ['Before comparing surprisal scores, what log-base check is needed?','Base 2 gives bits; natural logarithms give nats. Keep the unit consistent.'],
 ['Two independent fair-coin outcomes have joint probability 1/4. What is joint surprisal?','−log₂(1/4) = 2 bits; independent event surprisals add.'],
 ['What happens if a model assigns probability zero to an event that occurs?','Its log loss or surprisal is infinite; zero expresses impossibility, not merely rarity.']],{prerequisites:['info-surprise-intuition'],formula:'I(x) = −log₂ p(x)',checks:[{expression:'-Math.log2(1/8)',value:3},{expression:'-Math.log2(1/4)',value:2}]}),

 // Band 4: protecting estimates and diagnosing models.
 r(4,'papers','paper-preregistration','Transparent research','Preregistration',
 'Recording planned questions, outcomes and analyses before inspecting the relevant results.',
 'It separates prospective tests from discoveries made by exploring data.',
 'Timestamp the plan, report deviations and label unplanned analyses as exploratory.',
 'Writing your prediction before opening the envelope prevents rewriting it to match the answer.',[
 ['A researcher plans the main outcome after seeing which result is strongest. Is that preregistration?','No. The relevant plan must precede access to the results it is meant to constrain.'],
 ['A preregistered study cannot have bias or mistakes. What is wrong?','A recorded plan improves transparency but can still contain flawed design, measurement or analysis.'],
 ['How does exploratory analysis differ from a preregistered confirmatory test?','Exploration develops possible patterns; a prospective test checks a stated prediction with an appropriate plan.'],
 ['Before trusting the label \"preregistered\", what document should be checked?','The timestamped registration, its specificity, and consistency with the reported analysis.'],
 ['An unexpected subgroup appears interesting. What is a sound next step?','Report it as exploratory and test the subgroup prediction on new data.'],
 ['Why is it useful to report a justified change from the original plan?','Readers can assess why the change was made and whether results could have influenced it.']],{prerequisites:['paper-pvalue-reading'],sourceIds:['qres-preregister']}),
 r(4,'papers','paper-primary-outcome','Transparent research','Primary endpoint',
 'The main predefined outcome used to answer a study’s central question.',
 'It reduces ambiguity when many measurements point in different directions.',
 'Specify the primary endpoint, timing and analysis before viewing results.',
 'A competition needs a scoring rule before knowing who wins.',[
 ['A trial’s predefined primary endpoint is admission within 30 days. What is its central outcome?','Whether a participant is admitted within 30 days, using the planned definition.'],
 ['The primary endpoint fails, so a positive secondary endpoint becomes the main result without explanation. What is wrong?','Outcome switching hides the planned test and can inflate the impression of evidence.'],
 ['How can secondary outcomes still be useful?','They can show supporting patterns, harms or exploratory questions, with their status and multiplicity made clear.'],
 ['A paper lists several \"main\" outcomes. What testing issue should be checked?','Whether the plan specified multiple primary endpoints and handled their joint testing appropriately.'],
 ['A product test selects retention as primary but highlights clicks when retention falls. What should a reader ask?','What happened to the planned retention outcome and whether click findings are exploratory.'],
 ['Why can a surrogate endpoint be weaker than a direct patient outcome?','Changing a biomarker may not improve survival, function or well-being; the link needs evidence.']],{prerequisites:['paper-preregistration'],sourceIds:['qres-consort']}),
 r(4,'papers','paper-attrition','Study validity','Attrition and missing outcomes',
 'Participants or observations disappearing before their planned outcomes are measured.',
 'Missing results can bias comparisons if disappearance relates to outcomes.',
 'Report counts and reasons by group; assess how missing outcomes could change the conclusion.',
 'Judging a race only by runners who finish can hide what happened to those who stopped.',[
 ['A trial starts with 100 per group; 20 treated and 5 control participants lack outcomes. What are missing rates?','20% and 5%, a 15 percentage-point difference.'],
 ['Dropping missing participants always preserves randomization’s protection. What is wrong?','The remaining groups may differ if missingness depends on treatment or outcomes.'],
 ['How does missing completely at random differ from missing because symptoms worsen?','The first has no outcome-related selection; the second may systematically remove worse outcomes.'],
 ['Before accepting a complete-case analysis, what should be checked?','Why data are missing, whether assumptions are plausible, and sensitivity to alternative missing outcomes.'],
 ['Treatment completers look healthier but many sick treated participants left. What concern arises?','Attrition may make treatment appear better by excluding poor outcomes.'],
 ['Why is filling every missing value with the group mean not a general solution?','It can distort variability and relationships and ignores uncertainty and reasons for missingness.']],{prerequisites:['paper-randomization','paper-measurement'],sourceIds:['qres-trialbias'],checks:[{expression:'20-5',value:15}]}),
 r(4,'papers','paper-confounding','Causal interpretation','Confounding',
 'A common cause of exposure and outcome that can distort their association.',
 'It explains why exposed and unexposed groups can differ without an exposure effect.',
 'Identify plausible pre-exposure common causes using the study question and causal knowledge.',
 'Experience may influence both a trader’s tool choice and trading performance.',[
 ['Coffee users sleep less, and work stress increases both coffee use and poor sleep. What is the confounder?','Work stress, a possible common cause of exposure and outcome.'],
 ['Adjusting for any available variable always improves causal inference. What is wrong?','Some variables are mediators or colliders; adjustment can add bias.'],
 ['How does confounding differ from random sampling noise?','Confounding creates systematic distortion; noise creates chance variation across samples.'],
 ['Before claiming adjustment solved confounding, what unmeasured issue should be considered?','Important common causes may be missing, poorly measured or modeled incorrectly.'],
 ['High-risk borrowers pay higher rates and default more. Why not assume rates caused every default?','Baseline borrower risk can influence both pricing and default.'],
 ['Can a huge observational sample eliminate confounding by itself?','No. More observations improve precision but do not automatically make exposed groups comparable.']],{prerequisites:['paper-observation-experiment'],sourceIds:['qres-whatif']}),
 r(4,'papers','paper-reverse-causation','Causal interpretation','Reverse causation',
 'The outcome or its early causes influencing the supposed exposure.',
 'It prevents mistaking a response to a problem for the cause of that problem.',
 'Check temporal order and whether the outcome began before the exposure.',
 'People may start a health program because they became ill, making users look less healthy.',[
 ['A company hires consultants after profits fall. Does a consultant–low-profit association prove harm?','No. Falling profits may cause consultant hiring.'],
 ['A predictor was measured today, so it must cause next month’s outcome. What is wrong?','An earlier stage of the future outcome may already affect today’s predictor.'],
 ['How does reverse causation differ from confounding?','Reverse causation reverses the exposure–outcome direction; confounding involves a common cause of both.'],
 ['A paper links inactivity to disease. What timing evidence should be checked?','Whether illness or early symptoms reduced activity before the recorded diagnosis.'],
 ['Traders reduce size after losses. Why might small position size correlate with poor recent performance?','Poor performance triggered the size reduction, rather than small size causing those earlier losses.'],
 ['Why can measuring exposures before a diagnosis still leave reverse-causation risk?','The disease may have existed undiagnosed and already changed behavior.']],{prerequisites:['paper-confounding'],sourceIds:['qres-whatif']}),
 r(4,'models','model-rsquared','Model diagnostics','R-squared',
 'In ordinary in-sample regression with an intercept, the fraction of outcome variation accounted for relative to a mean-only baseline.',
 'It summarizes fit while reminding us to inspect residuals and future prediction.',
 'R² = 1 − SSE / SST; SST is squared deviation from the observed mean.',
 'A model can describe yesterday’s pattern well yet miss tomorrow’s results.',[
 ['A model has SSE 20 and SST 100. What is R-squared?','1 − 20 / 100 = 0.80, or 80% of in-sample variation accounted for.'],
 ['R-squared of 90% proves a causal explanation. What is wrong?','R-squared measures fit, not causal identification; confounding or leakage can create high fit.'],
 ['How does high R-squared differ from small prediction error in useful units?','R-squared is relative to outcome variability; practical error still needs a measure in relevant units.'],
 ['Even with high R-squared, what residual check matters?','Look for curvature, unequal error variance, dependence and influential observations.'],
 ['A model’s SSE equals SST. What is R-squared?','0%; by this measure it provides no improvement over the mean-only baseline on those data.'],
 ['Can held-out R-squared be negative?','Yes. If test errors exceed the test baseline errors, the model predicts worse than that baseline.']],{prerequisites:['model-least-squares'],formula:'R² = 1 − SSE / SST',sourceIds:['qres-nist'],checks:[{expression:'1-20/100',value:0.8},{expression:'1-100/100',value:0}]}),
 r(4,'models','model-multiple-regression','Multivariable models','Multiple regression',
 'A regression using more than one input to predict an outcome.',
 'It can represent several measured influences and conditional associations together.',
 'ŷ = a + b₁x₁ + b₂x₂; each coefficient is a modeled change with the other inputs fixed.',
 'House-price prediction may use both floor area and location, rather than one alone.',[
 ['Predicted cost = 10 + 2x + 3z. What is predicted cost at x = 4 and z = 2?','10 + 2 × 4 + 3 × 2 = 24 cost units.'],
 ['Adding income to a regression makes the remaining coefficient automatically causal. What is wrong?','Causal interpretation still needs justified adjustment and identification assumptions.'],
 ['How does a conditional coefficient differ from a simple two-variable association?','It describes the fitted relationship while the included other inputs are held fixed.'],
 ['Two inputs are almost identical. What estimation problem should be checked?','Multicollinearity can make separate coefficients unstable even if combined predictions are useful.'],
 ['A model adds €5 for each square meter, holding neighborhood fixed. What does 10 extra square meters predict?','€50 more, under the fitted linear relationship and within its supported range.'],
 ['Why can controlling for a post-treatment variable change the question being estimated?','It can block part of the treatment effect or introduce selection bias, rather than estimate the total effect.']],{prerequisites:['model-slope','paper-confounding'],formula:'ŷ = a + Σbjxj',checks:[{expression:'10+2*4+3*2',value:24},{expression:'5*10',value:50}]}),
 r(4,'product','product-guardrails','Product experiments','Guardrail metrics',
 'Metrics that must not worsen beyond acceptable limits while pursuing a main goal.',
 'They stop a narrow win from damaging users or the business elsewhere.',
 'Predefine the main goal and important harm thresholds, then assess them together.',
 'A car can go faster while still needing safe brakes; speed alone is not success.',[
 ['Clicks rise 8% but checkout crashes rise from 1% to 3%. What should be considered?','The +2 percentage-point crash increase may violate a guardrail despite the click gain.'],
 ['A higher primary metric means every other metric can be ignored. What is wrong?','The change may harm retention, performance, revenue quality or safety.'],
 ['How does a guardrail differ from the primary metric?','The primary metric measures the intended gain; a guardrail monitors a key unacceptable loss.'],
 ['Before interpreting a guardrail result, what threshold should be defined?','A meaningful harm margin and an appropriate uncertainty method, not a threshold chosen after seeing results.'],
 ['An experiment raises revenue €1,000 but increases expected refunds €1,400. What net effect is estimated?','€1,000 − €1,400 = −€400 before other costs.'],
 ['Why might a seven-day positive test still need retention follow-up?','Novelty can raise short-term activity while longer-term engagement or satisfaction falls.']],{prerequisites:['product-lift','paper-primary-outcome'],sourceIds:['qres-guardrails'],checks:[{expression:'3-1',value:2},{expression:'1000-1400',value:-400}]}),
 r(4,'information','info-entropy','Information measures','Entropy',
 'The average surprisal of outcomes under a probability distribution.',
 'It measures uncertainty before observing the next outcome.',
 'H(X) = −Σp(x)log₂p(x); weight each outcome’s surprisal by its probability.',
 'A fair coin is harder to predict than a coin that nearly always shows heads.',[
 ['What is the entropy of a fair coin in bits?','−0.5 log₂(0.5) − 0.5 log₂(0.5) = 1 bit.'],
 ['A completely certain outcome has the largest entropy. What is wrong?','A certain outcome has 0 bits; there is no outcome uncertainty.'],
 ['Compare a fair four-sided die with a fair two-sided coin.','Entropies are log₂4 = 2 bits and log₂2 = 1 bit.'],
 ['Before comparing entropies, what outcome-definition issue matters?','The categories, probabilities and log base must refer to the same type of distribution.'],
 ['A binary event has probabilities 75% and 25%. What is its entropy?','−0.75 log₂0.75 − 0.25 log₂0.25 ≈ 0.811 bits, below a fair coin’s 1 bit.'],
 ['Why is high entropy not the same as high economic value?','Entropy measures uncertainty, while economic value depends on whether resolving it improves a decision.']],{prerequisites:['info-surprisal'],formula:'H(X) = −Σp(x)log₂p(x)',checks:[{expression:'-0.75*Math.log2(0.75)-0.25*Math.log2(0.25)',value:0.8112781244591328}]})
);

skills.push(
 // Band 5: selection of analyses and outcomes.
 r(5,'papers','paper-multiple-testing','Research errors','Many hypothesis tests',
 'Testing many claims creates more opportunities to find chance positives.',
 'It puts an isolated low p-value in the context of the whole search.',
 'For m valid true-null tests at level α, expected false positives = mα; dependence affects the chance of at least one.',
 'Buying many lottery tickets raises the chance of at least one apparent winner.',[
 ['100 true-null tests each use a 5% threshold. How many false positives are expected?','100 × 0.05 = 5. This expectation does not require independence.'],
 ['One p = 0.04 found among 100 searches is equivalent to one planned p = 0.04. What is wrong?','The search creates extra chances for an apparently positive result; selection must be considered.'],
 ['For 20 independent true-null 5% tests, what is the chance of at least one false positive?','1 − 0.95²⁰ ≈ 64.2%. Independence is required for that calculation.'],
 ['Before choosing a multiple-testing correction, what family must be defined?','Which related claims count as the planned testing family, and whether the aim is family-wise or false-discovery control.'],
 ['A Bonferroni plan tests 10 endpoints with family-wise α = 5%. What threshold does each receive?','0.05 / 10 = 0.005, or 0.5%, for each test.'],
 ['Why is \"we only reported one test\" not enough to avoid multiplicity?','Unreported outcomes, model choices and subgroups may also have been searched.']],{prerequisites:['paper-primary-outcome','paper-pvalue-reading'],formula:'E(false positives) = mα; independent P(any) = 1 − (1 − α)^m',sourceIds:['qres-asa','qres-flex'],checks:[{expression:'100*0.05',value:5},{expression:'(1-0.95**20)*100',value:64.15140775914581},{expression:'0.05/10',value:0.005}]}),
 r(5,'papers','paper-optional-stopping','Research errors','Unplanned significance stopping',
 'Repeatedly checking an ordinary fixed-sample test and stopping when it looks significant.',
 'It prevents mistaking a transient fluctuation for a properly calibrated discovery.',
 'Use the planned sample rule or a valid sequential method that accounts for monitoring.',
 'Watching a noisy scoreboard until your team briefly leads is different from checking at a fixed final whistle.',[
 ['A test planned for 5,000 users is stopped at 600 when p first drops below 0.05. What changed?','The stopping rule became result-dependent; the ordinary fixed-sample p-value may no longer control false alarms at 5%.'],
 ['Checking every hour is harmless because each individual p-value uses 0.05. What is wrong?','Repeated chances to stop on a favorable fluctuation can raise overall false-positive risk.'],
 ['How does valid sequential monitoring differ from unplanned peeking?','It uses a method calibrated for repeated looks and its stated stopping rules.'],
 ['Before trusting an early-stopped result, what should be checked?','The preregistered stopping rule, number of looks and statistical method used.'],
 ['A feature causes obvious severe crashes. Must a company wait for the final analysis?','It can stop for safety; report the stopping reason and use appropriate inference rather than hide it.'],
 ['Why can early-stopped positive effects be exaggerated?','Stopping preferentially selects unusually favorable interim estimates.']],{prerequisites:['paper-preregistration','paper-multiple-testing'],sourceIds:['qres-sequential']}),
 r(5,'papers','paper-phacking','Research errors','P-hacking',
 'Using flexible choices to hunt for a favorable statistical result without honestly accounting for the search.',
 'It explains why neat low p-values can emerge from noisy data.',
 'Disclose outcomes, exclusions, models and stopping choices; test discoveries on independent data.',
 'Trying many keys until one opens the lock does not show that key was predicted in advance.',[
 ['A researcher tries 30 outcome definitions and reports only the one with p = 0.02. What is the issue?','Selective analysis search makes that p-value look more confirmatory than the full process warrants.'],
 ['Removing inconvenient observations after seeing significance is always harmless cleaning. What is wrong?','Outcome-driven exclusions can select a desired result; criteria and sensitivity analyses must be transparent.'],
 ['How does honest exploration differ from p-hacking?','Honest exploration reports the search and uncertainty; p-hacking conceals flexibility or treats a discovered result as planned evidence.'],
 ['A paper lists one final model. What analytical-history evidence would help?','The plan, all reasonable tried models, exclusions and whether results depend on particular choices.'],
 ['A trader tests 2,000 strategy settings on the same history and selects the best. What is a parallel concern?','Backtest overfitting and selection; evaluate the fixed strategy on new or properly held-out data.'],
 ['Why may p-hacking happen without conscious fraud?','Flexible decisions and confirmation incentives can select favorable outcomes unless procedures constrain and disclose the process.']],{prerequisites:['paper-multiple-testing','paper-optional-stopping'],sourceIds:['qres-flex']}),
 r(5,'papers','paper-harking','Research errors','HARKing',
 'Presenting a hypothesis developed after seeing results as though it was proposed beforehand.',
 'It distinguishes a compelling after-the-fact story from a risky prediction actually tested.',
 'Mark post-result ideas as exploratory and confirm them with new evidence.',
 'Drawing a target around the arrow after it lands makes the shot appear more accurate than it was.',[
 ['After finding an age subgroup effect, a paper claims it had predicted that exact subgroup. What is this called?','HARKing if the hypothesis was generated after seeing results but presented as prior.'],
 ['A plausible explanation written after the result counts as a successful advance prediction. What is wrong?','A fitting explanation is not the same evidential test as a prediction made before seeing data.'],
 ['How can a post hoc idea still advance science?','It can generate a clear hypothesis for a new, independent test.'],
 ['Before trusting a stated prior hypothesis, what timing evidence is useful?','A dated protocol, registration or documented prediction predating the relevant results.'],
 ['A founder explains an unexpected conversion gain with a new user-behavior theory. How should it be described?','As a possible exploratory explanation, with a new test designed to distinguish it from alternatives.'],
 ['Why can even a correctly predicted sign be weak evidence after many unspecified hypotheses?','A broad set of possible stories can fit many outcomes; specificity and the full search matter.']],{prerequisites:['paper-preregistration','paper-phacking'],sourceIds:['qres-preregister','qres-flex']}),
 r(5,'papers','paper-publication-bias','Research errors','Publication bias',
 'The available research differs systematically from all research conducted because some results are less likely to be reported.',
 'It warns that published studies can overstate benefit even if each published calculation is correct.',
 'Search registrations, unpublished results and missing outcomes, not only favorable articles.',
 'A wall displaying only winning lottery tickets hides all the losing tickets.',[
 ['Ten trials exist; only the three positive ones are published. What evidence is missing?','Seven trials, potentially including null or unfavorable findings.'],
 ['A meta-analysis includes every published paper, so publication bias is impossible. What is wrong?','Unpublished studies or omitted outcomes can still be missing.'],
 ['How does publication bias differ from a calculation error?','It selects which results are visible; individual visible calculations can be mathematically correct.'],
 ['Before trusting a complete evidence search, what registries should be checked?','Relevant trial or study registrations and other sources that reveal completed but unreported work.'],
 ['A supplement has five positive small papers and several registered trials with no results. What concern arises?','The missing results may change the apparent benefit; find their status before treating the published evidence as complete.'],
 ['Does every unpublished study have a negative result?','No. Reasons vary. Assess whether reporting depends on results rather than assuming the content of every missing study.']],{prerequisites:['paper-primary-outcome','paper-phacking'],sourceIds:['qres-missing']}),
 r(5,'models','model-dummy','Multivariable models','Dummy variables',
 'Zero–one indicators that represent a category in a model.',
 'They let categories enter a regression without inventing a numeric distance between labels.',
 'For k categories with an intercept, a standard coding uses k − 1 indicators and a reference category.',
 'A switch marked 1 for desktop and 0 for mobile lets a model include a category difference.',[
 ['Predicted spend = 20 + 5D, where D = 1 for desktop and 0 for mobile. What does each group predict?','Desktop €25 and mobile €20; the fitted gap is €5.'],
 ['Assigning countries codes 1, 2 and 3 makes country 3 three times country 1. What is wrong?','The codes are labels; their numeric distance has no automatic quantitative meaning.'],
 ['Why use two indicators rather than three for three categories with an intercept?','One category is the reference; all three indicators plus an intercept would be exactly redundant.'],
 ['Before interpreting a category coefficient, what must be identified?','The reference group and other variables held fixed in the model.'],
 ['A €4 desktop coefficient appears after adjusting for purchase count. What comparison does it represent?','The modeled spend gap between devices at the same included purchase-count value.'],
 ['Why might a device coefficient fail to show the effect of forcing mobile users onto desktop?','Device choice may reflect user differences; prediction coding does not establish a causal intervention.']],{prerequisites:['model-multiple-regression'],formula:'ŷ = a + bD; D ∈ {0,1}',checks:[{expression:'20+5',value:25}]}),
 r(5,'models','model-interaction','Multivariable models','Interaction',
 'A model feature allowing one input’s relationship with the outcome to depend on another input.',
 'It represents situations where a change works differently across conditions.',
 'With ŷ = a + bx + cz + dxz, the modeled x slope is b + dz.',
 'A discount may help new users more than loyal users; one average slope can hide the difference.',[
 ['A model is ŷ = 10 + 2x + 3z + 4xz. What is the x slope when z = 1?','2 + 4 × 1 = 6 outcome units per x unit.'],
 ['A positive subgroup result and a negative subgroup result automatically prove an interaction. What is wrong?','Compare subgroup effect estimates directly with uncertainty; separate significance labels are insufficient.'],
 ['In that model, how does the x slope change from z = 0 to z = 2?','It changes from 2 to 2 + 4 × 2 = 10, a difference of 8.'],
 ['Before treating an interaction as a discovery, what search issue must be checked?','Whether many subgroup or interaction analyses were explored and how multiplicity was handled.'],
 ['A discount adds 2 percentage points for existing users and 6 for new users. What is the estimated interaction gap?','6 − 2 = 4 percentage points; test its uncertainty rather than only each subgroup separately.'],
 ['Why is extrapolating an interaction far beyond observed input combinations risky?','There may be little data supporting those combinations, and the assumed form may be wrong.']],{prerequisites:['model-dummy','paper-multiple-testing'],formula:'ŷ = a + bx + cz + dxz; x slope = b + dz',checks:[{expression:'2+4*1',value:6},{expression:'2+4*2',value:10},{expression:'6-2',value:4}]}),
 r(5,'product','product-power','Product experiments','Power and detectable lift',
 'Power is the chance a planned test detects a specified real effect under its assumptions.',
 'It helps choose a test large enough to answer a meaningful business question.',
 'Set the minimum useful effect, baseline, false-alarm rate and desired power before collecting results.',
 'A weak flashlight can miss a small object; a weak test can miss a useful effect.',[
 ['A design has 80% power for a specified lift. What is its miss chance under that effect?','1 − 0.80 = 20%, under the design’s assumptions.'],
 ['No significance in an underpowered test proves there is no useful lift. What is wrong?','The test may lack enough precision to detect the lift.'],
 ['With the same baseline and error rates, roughly what happens to sample need when target lift halves?','It grows about fourfold under common large-sample approximations, because precision scales with 1/√n.'],
 ['Before using a sample-size calculator, what inputs must be checked?','Baseline rate, absolute target effect, allocation, error rates, power and the randomization/analysis unit.'],
 ['A 1-point lift needs about 10,000 users in a fixed design. What rough size detects 0.5 points?','About 40,000 users with the same other assumptions.'],
 ['Why can millions of page views still give less information than expected?','Repeated views from the same users are dependent; the effective sample follows the independent analysis units.']],{prerequisites:['product-lift','paper-ci-reading'],sourceIds:['qres-exp','qres-power'],checks:[{expression:'(1-0.8)*100',value:20},{expression:'10000*(1/0.5)**2',value:40000}]}),
 r(5,'information','info-cross-entropy','Prediction scoring','Cross-entropy',
 'Average surprisal under predicted probabilities, weighted by the true outcome distribution.',
 'It scores probabilistic predictions and penalizes confident wrong forecasts.',
 'H(P,Q) = −ΣP(x)log₂Q(x); P describes outcomes and Q is the prediction.',
 'Predicting an outcome as nearly impossible incurs a large penalty when it happens.',[
 ['A happened and the model assigned it probability 1/4. What is its log-loss in bits?','−log₂(1/4) = 2 bits.'],
 ['Cross-entropy only checks whether the most likely label was correct. What is wrong?','It also evaluates the assigned probabilities, so confidence matters.'],
 ['A occurs: compare predictions of 50% and 90% for A.','Losses are 1 bit and about 0.152 bits; the higher correct probability earns lower loss.'],
 ['Before averaging log losses, what outcome and unit checks matter?','Use the same target labels and log base, and appropriate weighting for the target population.'],
 ['For a fair binary outcome, a model predicts 75%/25%. What is average cross-entropy?','−0.5 log₂0.75 − 0.5 log₂0.25 ≈ 1.208 bits, worse than the correct 1-bit forecast.'],
 ['Why should a model avoid unjustified zero probabilities?','One observed event assigned zero makes log loss infinite and exposes an unsupported impossibility claim.']],{prerequisites:['info-entropy'],formula:'H(P,Q) = −ΣP(x)log₂Q(x)',sourceIds:['qres-logloss','qres-infotheory'],checks:[{expression:'-Math.log2(0.9)',value:0.15200309344504995},{expression:'-0.5*Math.log2(0.75)-0.5*Math.log2(0.25)',value:1.207518749639422}]}),

 // Band 6: repeated evidence and causal structure.
 r(6,'papers','paper-replication','Reliable evidence','Replication',
 'Testing a finding again using new observations.',
 'It checks whether evidence survives beyond one dataset and research team.',
 'Compare designs, effect estimates and uncertainty, not only whether both p-values cross 0.05.',
 'A recipe is more credible when another cook can produce the dish with new ingredients.',[
 ['An independent team reruns a planned experiment on new participants. What is being attempted?','A replication using fresh observations.'],
 ['The original has p = 0.04 and replication p = 0.06, so effects conflict. What is wrong?','The estimates and intervals may be similar; significance labels alone do not establish a difference.'],
 ['How does a direct replication differ from a conceptual replication?','Direct replication closely repeats the original procedure; conceptual replication tests the underlying claim with a different operationalization.'],
 ['Before judging a failed replication, what design issues should be checked?','Power, fidelity, population, measures, timing and whether the same effect was actually tested.'],
 ['An original estimate is 10 units and a precise replication is 2. What should be examined?','Selection inflation, heterogeneity, design differences and uncertainty; do not simply average the headlines.'],
 ['Why do several independent good studies matter more than repeating one analysis on the same data?','New observations test generalization; reusing one dataset can preserve the same bias and chance pattern.']],{prerequisites:['paper-ci-reading','paper-publication-bias'],sourceIds:['qres-replicate']}),
 r(6,'papers','paper-winners-curse','Reliable evidence','Winner’s curse in research',
 'Selected impressive estimates tend to overstate their underlying effects.',
 'It explains why follow-up effects can shrink without every original study being fraudulent.',
 'Account for selection and seek adequately precise independent estimates.',
 'The tallest wave you chose from a storm is larger than the typical wave you will see next.',[
 ['A researcher publishes only the largest of 30 noisy positive effects. What bias is likely?','The selected effect is likely inflated relative to its underlying value.'],
 ['A replication effect is smaller, therefore the original author must have fabricated data. What is wrong?','Chance, selection and setting differences can cause shrinkage; fabrication needs separate evidence.'],
 ['Why does low power worsen selected effect inflation?','Small noisy studies often need unusually large observed estimates to pass a significance threshold.'],
 ['Before using a published large effect for power planning, what should be checked?','Its uncertainty and selection history; use conservative relevant evidence rather than assume the peak estimate is true.'],
 ['A 40-person pilot shows a huge gain. What design is better for confirmation?','A preregistered, adequately powered independent study with the same meaningful outcome.'],
 ['Why can honest researchers all report exaggerated effects?','Each may preferentially publish unusually favorable noisy findings, creating selection across the literature.']],{prerequisites:['paper-replication','paper-phacking'],sourceIds:['qres-power','qres-missing']}),
 r(6,'papers','paper-dag','Causal reasoning','Causal diagrams',
 'Directed graphs that state assumed causal relationships between variables.',
 'They clarify which paths can bias a causal comparison.',
 'Draw arrows from causes to effects; choose adjustment based on the question and graph assumptions.',
 'A route map helps distinguish a road through a common cause from the road of the treatment effect.',[
 ['A diagram has stress → coffee and stress → poor sleep. What role can stress play?','A confounder: a common cause of exposure and outcome.'],
 ['An arrow drawn on a diagram proves the causal relation exists. What is wrong?','The graph records assumptions; evidence and subject knowledge must justify them.'],
 ['How does a mediator differ from a confounder in a diagram?','A mediator lies on a treatment-to-outcome path; a confounder is a common cause of both.'],
 ['Before using a diagram to adjust a regression, what must be specified?','The exposure, outcome, causal effect of interest and plausible temporal relationships.'],
 ['Training → skill → income. For the total training effect, why not automatically adjust for skill?','Skill mediates part of the effect; adjusting can block that part of the total pathway.'],
 ['Why should a graph include selection into the analyzed sample?','Conditioning on selection can open biased paths even when measured exposure and outcome seem well controlled.']],{prerequisites:['paper-confounding','paper-reverse-causation'],sourceIds:['qres-whatif']}),
 r(6,'papers','paper-collider','Causal reasoning','Collider bias',
 'Bias that can arise from conditioning on a common effect of two variables.',
 'It warns that adding controls or selecting a subgroup can create an association.',
 'For A → C ← B, conditioning on collider C can associate A and B even without a causal link.',
 'Among admitted students, a weaker test score may be offset by stronger sports skill, creating an apparent tradeoff.',[
 ['Admission depends on grades and sports ability. Why can admitted students show a grades–sports tradeoff?','Conditioning on admission, their common effect, can create collider bias.'],
 ['Every variable related to both groups should be controlled. What is wrong?','A common effect can be a collider, and conditioning on it may add bias.'],
 ['How does a collider differ from a confounder?','A collider is caused by both variables; a confounder causes both. Their adjustment consequences differ.'],
 ['Before controlling for hospitalization in a disease study, what causal check is needed?','Whether hospitalization is influenced by both exposure and illness severity, making it a potential collider.'],
 ['A trader studies only stocks that doubled; news quality and speculation can both drive doubling. What can selection do?','It can induce a misleading relationship between news quality and speculation within that selected group.'],
 ['Why can restricting to people with measured outcomes introduce collider bias?','Being measured may depend on exposure and outcome-related factors; conditioning on it can open a noncausal path.']],{prerequisites:['paper-dag'],sourceIds:['qres-whatif'],formula:'A → C ← B; conditioning on C can open a path'}),
 r(6,'papers','paper-selection','Study validity','Selection into a study',
 'How people or observations become eligible, recruited and included in an analysis.',
 'It reveals whether analyzed results describe the desired target or a distorted subset.',
 'Track eligibility, recruitment, participation and analysis exclusions separately.',
 'A net with large holes catches a different mix of fish than a fine net.',[
 ['A survey recruits through a luxury newsletter. What population mismatch is possible?','Readers may be wealthier and have different preferences than the intended general population.'],
 ['A dataset includes one million surviving firms, so survival bias is negligible. What is wrong?','Large size does not restore failed firms excluded by the selection rule.'],
 ['How does initial recruitment differ from post-treatment attrition?','Recruitment determines who enters; attrition determines whose planned outcomes remain after entry.'],
 ['Before generalizing from volunteers, what participation question should be asked?','Could willingness or ability to participate be related to the exposure, outcome or treatment response?'],
 ['A poker study includes only players who stayed profitable for a year. What is missing?','Losing and quitting players; the sample cannot fairly describe all starters’ outcomes.'],
 ['Why can conditioning on a selected sample harm both representativeness and causal validity?','The sample can differ from the target population and selection can open noncausal paths.']],{prerequisites:['paper-population','paper-attrition','paper-collider'],sourceIds:['qres-whatif','qres-trialbias']}),
 r(6,'models','model-logistic','Probability models','Logistic regression',
 'A model that maps a linear score to a probability between zero and one.',
 'It models binary outcomes such as purchase, default or churn.',
 'p = 1 / (1 + e^(−z)); z is the fitted linear score, representing log-odds.',
 'An S-shaped curve keeps predicted chances within 0% and 100%.',[
 ['A logistic model has score z = 0. What probability does it predict?','1 / (1 + e⁰) = 0.5, or 50%.'],
 ['A logistic coefficient of 0.2 means a 20 percentage-point rise everywhere. What is wrong?','It changes log-odds; the probability change depends on the starting score and other inputs.'],
 ['If an input coefficient is ln(2), what happens to odds for a one-unit rise?','Odds multiply by e^ln(2) = 2, holding the other modeled inputs fixed.'],
 ['Before using logistic predictions for decisions, what should be checked beyond discrimination?','Calibration on relevant held-out data: do predicted probabilities match outcome frequencies?'],
 ['A logistic score is ln(3). What probability is predicted?','Odds are 3, so p = 3 / (1 + 3) = 75%.'],
 ['Why might a logistic model with perfect training separation need regularization?','Unpenalized coefficients can diverge while fitting the training labels; held-out prediction and complexity control matter.']],{prerequisites:['model-multiple-regression'],formula:'p = 1 / (1 + e^(−z)); odds = e^z',sourceIds:['qres-google','qres-logloss'],checks:[{expression:'1/(1+Math.exp(0))',value:0.5},{expression:'1/(1+Math.exp(-Math.log(3)))',value:0.75}]}),
 r(6,'models','model-transforms','Model specification','Log transforms',
 'Representing a positive variable by its logarithm to model multiplicative relationships.',
 'They can express percentage effects and reduce extreme scale differences.',
 'State whether the model uses log outcome, log input or both; their interpretations differ.',
 'Growth from 100 to 110 and from 1,000 to 1,100 has the same 10% proportional change.',[
 ['A log-log model has slope 0.5. Approximately what outcome change accompanies a small 1% input rise?','About +0.5%, under the fitted relationship; the slope is an elasticity.'],
 ['A coefficient of 0.1 on an unlogged input in a log-outcome model means exactly 10%. What is wrong?','The exact one-unit effect is e^0.1 − 1 ≈ 10.52%; 10% is a small-change approximation.'],
 ['How does a level-level slope differ from a log-log slope?','Level-level uses outcome units per input unit; log-log describes proportional outcome change per proportional input change.'],
 ['Before taking logs, what data issue must be checked?','Ordinary real logarithms require positive values; zero or negative observations need a justified approach.'],
 ['A model predicts log revenue rising by ln(1.2). What proportional revenue change does this represent?','e^ln(1.2) − 1 = 20%.'],
 ['Why is exponentiating an average predicted log value not automatically a prediction of the arithmetic mean?','Exponentiation is nonlinear; retransformation bias and the residual distribution must be considered.']],{prerequisites:['model-slope','model-multiple-regression'],formula:'log-log slope = elasticity; exact log-level effect = e^b − 1',sourceIds:['qres-google','qres-nist'],checks:[{expression:'(Math.exp(0.1)-1)*100',value:10.517091807564771},{expression:'(Math.exp(Math.log(1.2))-1)*100',value:20}]}),
 r(6,'product','product-cohorts','Product metrics','Cohort retention and churn',
 'Tracking the same entry group over time to see how many remain active or paying.',
 'It separates customer durability from growth that masks losses.',
 'Define the cohort, activity rule and interval; retention = remaining / starting cohort.',
 'A full bucket can hide a leak when a hose keeps adding water; cohorts reveal the leak.',[
 ['A January cohort starts with 500 users and 300 are active at day 30. What is day-30 retention?','300 / 500 × 100% = 60%, using the stated activity definition.'],
 ['Total users grew, so churn must have fallen. What is wrong?','New users can replace departing users; inspect existing cohorts.'],
 ['For a closed subscription cohort with no reactivation, how do 80% retention and churn relate?','Churn is 20% over that same period. Definitions must use the same cohort and window.'],
 ['Before comparing January and June cohorts, what maturity check is needed?','Both need the same time since entry; a newer cohort has not yet had equal follow-up.'],
 ['Of 1,000 paying users at month start, 50 cancel during the month. What is logo churn?','50 / 1,000 = 5% for that month; revenue churn can differ if customers pay different amounts.'],
 ['Why can day-1 retention improve while long-run customer value falls?','Early activity may rise but later retention, margins or paid conversion can worsen.']],{prerequisites:['product-conversion','product-guardrails'],sourceIds:['qres-stripe','qres-guardrails'],formula:'retention = retained / original cohort; closed-cohort churn = 1 − retention',checks:[{expression:'300/500*100',value:60},{expression:'50/1000*100',value:5}]}),
 r(6,'information','info-kl','Information measures','KL divergence',
 'The extra expected log loss from using distribution Q instead of the true distribution P.',
 'It quantifies a probability-model mismatch rather than merely a label error.',
 'D_KL(P || Q) = ΣP(x)log₂(P(x)/Q(x)) = H(P,Q) − H(P).',
 'Using the wrong code for a source wastes expected bits; KL measures that waste.',[
 ['A fair coin has entropy 1 bit and a forecast has cross-entropy 1.208 bits. What is KL divergence?','About 1.208 − 1 = 0.208 bits per outcome.'],
 ['KL is a symmetric distance, so swapping distributions gives the same value. What is wrong?','KL is generally asymmetric and is not a metric.'],
 ['What is KL when P and Q are identical on all outcomes?','0, because the model adds no expected log-loss penalty.'],
 ['Before computing finite KL, what support condition matters?','Q must assign positive probability wherever P has positive probability; otherwise KL can be infinite.'],
 ['P puts all mass on A, while Q assigns A probability 1/4. What is D_KL(P || Q)?','log₂(1 / (1/4)) = 2 bits.'],
 ['Why can a small average KL still hide a dangerous rare-outcome miss?','A low-probability event contributes little average weight but may have a large decision cost.']],{prerequisites:['info-cross-entropy'],formula:'D_KL(P || Q) = ΣP(x)log₂(P(x)/Q(x))',sourceIds:['qres-infotheory'],checks:[{expression:'-0.5*Math.log2(0.75)-0.5*Math.log2(0.25)-1',value:0.207518749639422},{expression:'Math.log2(1/0.25)',value:2}]})
);

skills.push(
 // Band 7: combining evidence and testing generalization.
 r(7,'papers','paper-meta-analysis','Evidence synthesis','Meta-analysis',
 'Statistically combining estimates from several separate studies.',
 'It can improve precision and reveal whether findings agree across settings.',
 'Pool compatible estimands with an appropriate model, while assessing study quality and missing evidence.',
 'Several thermometers can sharpen an estimate, but averaging broken thermometers does not repair them.',[
 ['Three equally weighted studies estimate effects of 2, 4 and 6 units. What is their pooled average?','(2 + 4 + 6) / 3 = 4 units, under the equal-weight illustration.'],
 ['Twenty weak studies pooled together guarantee strong causal evidence. What is wrong?','Shared bias, missing evidence or incompatible questions can remain after pooling.'],
 ['How does a meta-analysis differ from a single large trial?','It combines separate studies with potentially different designs, populations and biases; it is not one randomized dataset.'],
 ['Before combining treatment effects, what compatibility question matters?','Whether outcomes, comparison conditions, follow-up times and effect definitions answer a sufficiently common question.'],
 ['Ten positive small studies are published but many registered studies have no results. What must synthesis assess?','Risk of missing evidence and selective reporting, not just the average of available positives.'],
 ['Why should a systematic review sometimes avoid calculating a pooled estimate?','If differences in questions or bias make one average misleading, a structured comparison may be more useful.']],{prerequisites:['paper-replication','paper-publication-bias'],sourceIds:['qres-meta','qres-missing'],checks:[{expression:'(2+4+6)/3',value:4}]}),
 r(7,'papers','paper-inverse-variance','Evidence synthesis','Inverse-variance weighting',
 'Giving more weight to more precise study estimates in a suitable meta-analysis.',
 'It prevents a very noisy small estimate from counting the same as a much more precise estimate.',
 'Common-effect weight wi = 1 / SEi²; pooled estimate = Σwiθi / Σwi.',
 'A sharp photograph contributes more detail than a blurry photograph of the same scene.',[
 ['Study A has SE 1 and B has SE 2. What are their inverse-variance weights?','A: 1 / 1² = 1; B: 1 / 2² = 0.25. A gets four times the weight.'],
 ['A larger reported benefit deserves larger inverse-variance weight. What is wrong?','Weight depends on precision, not on the effect’s favorable size.'],
 ['With effects 2 and 6 and weights 1 and 0.25, what is the pooled estimate?','(1 × 2 + 0.25 × 6) / 1.25 = 2.8 units.'],
 ['Before applying the simple common-effect calculation, what study assumptions matter?','Independent compatible estimates, correctly measured standard errors and an appropriate shared-effect interpretation.'],
 ['For total independent inverse-variance weight 1.25, what is the common-effect pooled SE?','√(1 / 1.25) ≈ 0.894 units, under the model assumptions.'],
 ['Why can inverse-variance weighting still produce a biased pooled result?','Precision weights do not remove each study’s bias or selection in which studies were available.']],{prerequisites:['paper-meta-analysis','paper-ci-reading'],formula:'wi = 1 / SEi²; θ̂ = Σwiθi / Σwi',sourceIds:['qres-meta'],checks:[{expression:'1/2**2',value:0.25},{expression:'(1*2+0.25*6)/1.25',value:2.8},{expression:'Math.sqrt(1/1.25)',value:0.8944271909999159}]}),
 r(7,'papers','paper-heterogeneity','Evidence synthesis','Between-study heterogeneity',
 'Differences in underlying effects across studies beyond their sampling variation.',
 'It warns that one pooled mean may not describe every setting.',
 'Investigate population, intervention, outcome and design differences; report suitable heterogeneity and prediction uncertainty.',
 'An average temperature can hide a cold mountain and a hot coast.',[
 ['Two precise studies estimate benefit in one setting and harm in another. What synthesis concern arises?','Possible heterogeneity; averaging them can hide meaningful effect differences.'],
 ['I² of 60% means 60% of studies are wrong. What is wrong?','I² concerns the share of observed variation attributed to between-study heterogeneity under its calculation, not a count of false studies.'],
 ['How does a random-effects mean differ from a universal treatment effect?','It summarizes a distribution of related effects; it does not claim every setting has that mean effect.'],
 ['Before interpreting I² from three small studies, what uncertainty issue matters?','Heterogeneity estimates can be very imprecise with few studies; avoid rigid labels.'],
 ['A pooled mean is +4 with a prediction interval from −2 to +10. What does the wider range indicate?','A comparable new setting may have a different true effect, potentially including harm, under the model.'],
 ['Why is choosing fixed versus random effects only by a heterogeneity p-value poor practice?','The choice should reflect the estimand, assumptions and scientific context; the test can have low or excessive power.']],{prerequisites:['paper-inverse-variance'],sourceIds:['qres-meta']}),
 r(7,'papers','paper-funnel','Evidence synthesis','Funnel-plot interpretation',
 'Examining effect estimates against study precision to look for small-study patterns.',
 'It can flag missing-evidence or other differences requiring investigation.',
 'Asymmetry is a clue, not proof of publication bias; consider alternative explanations.',
 'If small blurry pictures show only dramatic benefits, ask why less dramatic small pictures are absent.',[
 ['Small studies show larger benefits than large studies. What should be investigated?','Publication or reporting bias, heterogeneity, study quality and other small-study differences.'],
 ['An asymmetric funnel plot proves all large effects are fabricated. What is wrong?','Asymmetry has several causes and does not prove fabrication or one specific bias.'],
 ['How do imprecise studies usually differ from precise ones in an unbiased common-effect funnel?','Their estimates scatter more widely around the underlying effect.'],
 ['A review has only four studies. What limits a funnel-plot conclusion?','There is little information to distinguish a real pattern from chance or heterogeneity.'],
 ['A registry reveals missing small trials with null findings. How does this affect an asymmetric funnel concern?','It gives direct evidence consistent with selective availability, stronger than the plot alone.'],
 ['Why can a symmetric funnel still leave publication bias unresolved?','Some selection mechanisms preserve symmetry, and small numbers can conceal patterns.']],{prerequisites:['paper-heterogeneity','paper-publication-bias'],sourceIds:['qres-missing']}),
 r(7,'papers','paper-systematic-review','Evidence synthesis','Systematic evidence search',
 'A planned, reproducible process for finding and selecting relevant research.',
 'It reduces cherry-picking of studies that fit a preferred conclusion.',
 'Specify eligibility and search methods; record exclusions, duplicates and study-level risk of bias.',
 'A shopping list made before entering the store is harder to rewrite around whichever items look attractive.',[
 ['A review uses predefined criteria and searches several databases and registries. What feature makes it systematic?','A transparent reproducible process for finding and selecting eligible evidence.'],
 ['Five papers are selected because their conclusions agree with the author. What is wrong?','Selection is driven by the desired answer rather than a predefined evidence question.'],
 ['How does a narrative overview differ from a systematic review?','A narrative overview may be useful explanation, but it need not use a comprehensive reproducible selection process.'],
 ['Two papers analyze the same participants. What counting issue should be checked?','Avoid treating the same cohort as two independent sources of evidence.'],
 ['A review excludes every non-significant study. How does that affect its estimate?','It selects by outcome and can overstate effects; significance should not determine evidence eligibility.'],
 ['Why is a careful search insufficient if included studies share a flawed design?','Completeness addresses missing evidence, while study validity still determines what the evidence can establish.']],{prerequisites:['paper-meta-analysis','paper-funnel'],sourceIds:['qres-meta','qres-missing']}),
 r(7,'models','model-cross-validation','Model validation','Cross-validation',
 'Repeatedly training on one part of data and evaluating on a separate held-out part.',
 'It estimates how a modeling procedure performs beyond the observations used to fit it.',
 'Split independent units appropriately; fit all learned preprocessing inside each training fold.',
 'Practice on some exam questions, then try different questions you did not use to learn the answers.',[
 ['With 1,000 observations and five equal folds, how many are held out each round?','200 held out and 800 used for training, assuming a standard five-fold split.'],
 ['Scaling all data before splitting cannot leak information. What is wrong?','Learned preprocessing can use held-out information; estimate scaling from each training split.'],
 ['How does validation error differ from training error?','Training error uses data involved in fitting; validation error uses observations held aside for that evaluation.'],
 ['Several rows belong to each patient. What fold check matters?','Keep the relevant patient groups separated if evaluating prediction for new patients.'],
 ['A model scores 99% in training but 60% in suitable held-out data. What concern arises?','Overfitting, leakage or distribution mismatch; the training score is not a reliable deployment estimate.'],
 ['Why can repeatedly choosing the best model on the same folds overstate performance?','The validation results become part of model selection; use an outer evaluation or untouched test set.']],{prerequisites:['model-least-squares','model-rsquared'],sourceIds:['qres-splits','qres-nested','qres-leakage'],checks:[{expression:'1000/5',value:200},{expression:'1000-1000/5',value:800}]}),
 r(7,'models','model-regularization','Model validation','Regularization',
 'Constraining a fitted model’s complexity to reduce unstable fitting of noise.',
 'It can improve future prediction even if the training fit becomes less perfect.',
 'Choose a penalty strength using suitable validation; preserve an independent final evaluation.',
 'A flexible ruler can bend through every point; a stiffer ruler may follow the durable trend better.',[
 ['Ridge uses SSE + λΣb². If SSE = 10, λ = 2 and coefficients are 1 and 2, what is the objective?','10 + 2 × (1² + 2²) = 20.'],
 ['A larger regularization penalty always improves predictions. What is wrong?','Too much penalty can underfit useful structure; choose it using relevant validation.'],
 ['How do ridge and lasso penalties differ?','Ridge penalizes squared coefficients; lasso penalizes absolute coefficients and can set some exactly to zero.'],
 ['Before comparing penalty effects across inputs, what scale check matters?','Input scaling can change the meaning of coefficient penalties; standardization must be learned without leakage.'],
 ['A smaller model has slightly worse training loss but better test loss. Which may be preferable?','The smaller model, if the test is valid and matches the intended use.'],
 ['Why does selecting a variable with lasso not prove it is a causal driver?','Selection is predictive and data-dependent; causal interpretation requires separate identification assumptions.']],{prerequisites:['model-cross-validation','model-multiple-regression'],formula:'ridge objective = SSE + λΣbj²',sourceIds:['qres-logloss','qres-nested'],checks:[{expression:'10+2*(1**2+2**2)',value:20}]}),
 r(7,'product','product-unit-economics','Product economics','Customer lifetime value and acquisition cost',
 'Comparing a customer’s expected lifetime contribution with the cost to acquire that customer.',
 'It tests whether growth can create value rather than merely increase user counts.',
 'With contribution at each period’s start before constant churn c, constant contribution m and no discounting, simple LTV ≈ m/c.',
 'Filling a leaky bucket is worthwhile only if the retained water is worth more than the pumping cost.',[
 ['Monthly revenue is €20, contribution margin 80% and monthly churn 5%. What is simple contribution LTV?','€16 monthly contribution / 0.05 = €320, assuming period-start contribution before constant churn and no discounting.'],
 ['€320 lifetime revenue means €320 available to pay acquisition costs. What is wrong?','Revenue is not contribution; servicing costs, timing and uncertainty must be included.'],
 ['A product earns €2,000 from 400 total users, including 100 payers. What are ARPU and ARPPU?','ARPU = €2,000 / 400 = €5; ARPPU = €2,000 / 100 = €20 for that period.'],
 ['Before relying on LTV = margin/churn, what assumptions need checking?','Stable churn and margins, matching periods, billing timing, discounting and whether new cohorts behave similarly.'],
 ['Estimated contribution LTV is €320 and CAC is €80. What are the ratio and remaining contribution?','LTV/CAC = 4; €320 − €80 = €240 before other overhead and uncertainty.'],
 ['Why can profitable lifetime economics still create a cash crisis?','Acquisition spending happens now while customer contribution arrives later; payback timing and available cash matter.']],{prerequisites:['product-cohorts','paper-practical-significance'],formula:'simple LTV ≈ monthly contribution / monthly churn; CAC = acquisition cost / new customers',sourceIds:['qres-stripe'],checks:[{expression:'20*0.8/0.05',value:320},{expression:'2000/400',value:5},{expression:'2000/100',value:20},{expression:'320/80',value:4},{expression:'320-80',value:240}]}),
 r(7,'information','info-mutual-information','Information measures','Mutual information',
 'How much knowing one variable reduces uncertainty about another.',
 'It measures shared statistical information, including some nonlinear relationships.',
 'I(X;Y) = H(X) − H(X|Y); use a suitable joint distribution.',
 'A clue that completely identifies a hidden fair coin removes its one bit of uncertainty.',[
 ['A fair binary outcome has H(Y) = 1 bit and a perfect clue leaves H(Y|X) = 0. What is mutual information?','1 − 0 = 1 bit.'],
 ['Mutual information proves X causes Y. What is wrong?','It measures dependence; common causes or reverse direction can also produce shared information.'],
 ['What is mutual information when two variables are independent?','0, because knowing one does not change uncertainty about the other.'],
 ['Before interpreting estimated mutual information, what finite-data issue matters?','Estimation bias and uncertainty, especially with many categories or sparse observations.'],
 ['A fair binary label is observed through independent 25% flip noise. What is mutual information?','1 − H(binary 0.25) ≈ 1 − 0.811 = 0.189 bits.'],
 ['Why can two separately informative features add little information when combined?','Their information may overlap; duplicate clues do not double what you learn.']],{prerequisites:['info-entropy','info-kl'],formula:'I(X;Y) = H(X) − H(X|Y)',sourceIds:['qres-infotheory'],checks:[{expression:'1+0.25*Math.log2(0.25)+0.75*Math.log2(0.75)',value:0.18872187554086717}]}),

 // Band 8: credible non-randomized designs and deployment checks.
 r(8,'papers','paper-instrument','Causal designs','Instrumental variables',
 'Using a source of exposure variation that affects the outcome only through the exposure, under additional assumptions.',
 'It can help identify a causal effect when direct treatment choice is confounded.',
 'Check relevance, independence, exclusion and any assumptions needed for the target effect, such as monotonicity.',
 'A random encouragement can change who takes a program, while not directly changing the outcome except through participation.',[
 ['A randomized invitation raises treatment uptake by 20 percentage points and outcomes by 4. What is the simple Wald estimate?','0.04 / 0.20 = 0.20, a 20 percentage-point effect for compliers under the required binary-instrument assumptions.'],
 ['An instrument strongly predicts treatment, so it is automatically valid. What is wrong?','Relevance alone is insufficient; confounding or a direct outcome path can invalidate it.'],
 ['How does an invitation effect differ from an estimated treatment effect among compliers?','The invitation effect concerns assignment; the complier treatment effect scales it by the uptake change under assumptions.'],
 ['A college-distance instrument may influence local job opportunities. What assumption is threatened?','Exclusion: distance may affect earnings through paths other than college attendance.'],
 ['A proposed instrument changes uptake by only 1 percentage point. What concern arises?','A weak first stage can make estimation unstable and sensitive to bias; assess instrument strength and appropriate inference.'],
 ['Why should a local complier effect not be called the effect for everyone?','Compliers are people whose treatment changes with the instrument; effects may differ for always-takers or never-takers.']],{prerequisites:['paper-dag','paper-confounding'],formula:'Wald effect = outcome difference by instrument / treatment-uptake difference',sourceIds:['qres-whatif'],checks:[{expression:'0.04/0.2',value:0.2}]}),
 r(8,'papers','paper-rd','Causal designs','Regression discontinuity',
 'Comparing outcomes just around a cutoff that changes treatment assignment.',
 'It can estimate a local effect when otherwise similar people fall on different sides of a threshold.',
 'Check continuity of untreated outcomes near the cutoff, sorting and other changes at the same threshold.',
 'Students just above and below a scholarship score can be similar, apart from eligibility.',[
 ['A scholarship starts at score 80. What comparison is central to a local discontinuity design?','Applicants just above versus just below 80, with suitable modeling and assumptions.'],
 ['A cutoff estimate at score 80 establishes the effect for every applicant. What is wrong?','The identified effect is local to the cutoff unless stronger transport assumptions are justified.'],
 ['How does a sharp design differ from a fuzzy discontinuity?','In a sharp design treatment follows the cutoff exactly; in a fuzzy design treatment probability jumps but does not become 0 or 1.'],
 ['If applicants can precisely manipulate their scores, what concern arises?','Sorting near the cutoff may make groups systematically different, threatening local comparability.'],
 ['Outcome jumps by 2 units and treatment probability jumps by 0.5 at a valid fuzzy cutoff. What is the local ratio?','2 / 0.5 = 4 units under the relevant instrumental-variable assumptions.'],
 ['Why check whether another policy also starts at the same cutoff?','It could create its own outcome jump, preventing attribution to the intended treatment alone.']],{prerequisites:['paper-instrument','model-slope'],sourceIds:['qres-rd'],checks:[{expression:'2/0.5',value:4}]}),
 r(8,'papers','paper-did','Causal designs','Difference-in-differences',
 'Comparing a treated group’s before–after change with an untreated group’s change.',
 'It subtracts a shared trend when a credible untreated comparison is available.',
 'DiD = treated change − control change; causal interpretation requires appropriate counterfactual parallel trends.',
 'If both boats rise with the tide, subtract the common rise before judging one boat’s new motor.',[
 ['Treated sales go 120 to 150; control sales go 80 to 90. What is the DiD?','(150 − 120) − (90 − 80) = 30 − 10 = 20 sales units.'],
 ['A before–after gain of 30 is the treatment effect even if control rises 10. What is wrong?','A shared trend may explain 10 units; the simple DiD estimate is 20 under its assumptions.'],
 ['Does matching past trends prove counterfactual parallel trends after treatment?','No. It supports plausibility but cannot directly observe what treated outcomes would have done untreated.'],
 ['A new tax affects only the treated region at the same time. What validity issue arises?','The separate shock can break the untreated comparison, confounding the treatment estimate.'],
 ['Treatment begins at different dates with effects varying over time. What modeling warning matters?','A naive two-way fixed-effects average can be misleading; use a method appropriate to treatment timing and heterogeneity.'],
 ['Why should anticipatory behavior be checked before the official start date?','People may react early, so the supposed untreated pre-period may already contain treatment effects.']],{prerequisites:['paper-confounding','paper-comparison'],formula:'DiD = (YT,after − YT,before) − (YC,after − YC,before)',sourceIds:['qres-did'],checks:[{expression:'(150-120)-(90-80)',value:20}]}),
 r(8,'papers','paper-matching','Causal designs','Matching and propensity scores',
 'Comparing exposed and unexposed observations with similar measured pre-exposure characteristics.',
 'It can improve comparability when random assignment is unavailable.',
 'Propensity score is P(treatment | measured baseline covariates); causal use needs adequate overlap and no relevant unmeasured confounding.',
 'Compare borrowers with similar known risk rather than a wealthy safe borrower with a struggling risky one.',[
 ['Two groups have similar measured age, income and prior health after matching. What improved?','Balance on those measured characteristics, not guaranteed balance on every unmeasured cause.'],
 ['Matching turns observational data into a randomized experiment. What is wrong?','Unmeasured confounding and model or overlap problems can remain.'],
 ['How does a propensity score differ from an outcome prediction?','It predicts exposure assignment from baseline characteristics, not the study outcome.'],
 ['Treated people have scores near 0.95 while controls are near 0.05. What concern arises?','Poor overlap; there may be no comparable controls for the treated group.'],
 ['A matched design uses post-treatment spending as a matching variable. Why is this risky?','The variable may be affected by treatment and can block effects or induce bias.'],
 ['Why report who was excluded by matching?','The estimand may shift to the subset with comparable controls, limiting generalization.']],{prerequisites:['paper-dag','paper-selection','model-logistic'],sourceIds:['qres-whatif'],formula:'propensity e(X) = P(A = 1 | baseline X)'}),
 r(8,'papers','paper-mediation','Causal designs','Mediation and bad controls',
 'Distinguishing the total effect from pathways that operate through intermediate variables.',
 'It prevents adjusting away the effect we intended to estimate.',
 'Choose the causal estimand first; controlling a mediator does not automatically identify a direct effect.',
 'If a reminder raises renewals by causing app visits, controlling visits can remove part of the reminder’s pathway.',[
 ['Reminder → visit → renewal. Is visit a mediator of the reminder’s effect?','Yes, under that causal structure: it lies on a pathway from reminder to renewal.'],
 ['Add every post-treatment behavior to estimate the total effect more accurately. What is wrong?','This can block mediated effects or introduce collider bias.'],
 ['How does a total effect differ from a direct effect?','The total includes all causal pathways; a specified direct effect concerns changing treatment while controlling or intervening on a mediator in a defined way.'],
 ['Before estimating a mediator’s contribution, what extra identification issue matters?','Mediator–outcome confounding and treatment-induced confounders can require stronger assumptions than the total randomized effect.'],
 ['A training course changes skill and job access. Why may a regression controlling skill miss total benefit?','It removes a skill pathway and may estimate a different, potentially biased quantity.'],
 ['Why is the difference between adjusted and unadjusted coefficients not automatically the mediated effect?','Nonlinearity, confounding, collider bias and changing scales can alter coefficients without clean causal mediation.']],{prerequisites:['paper-dag','paper-collider','paper-matching'],sourceIds:['qres-whatif']}),
 r(8,'models','model-leakage','Deployment validity','Data leakage',
 'Using information during training or evaluation that would not be available for the intended live prediction.',
 'It explains suspiciously good model scores that fail in practice.',
 'Respect prediction time and fit preprocessing or feature selection only on the training portion of each evaluation.',
 'Seeing the answer key during practice makes the exam score look impressive without showing real ability.',[
 ['A default model uses the collection action taken after default. What leaked?','A later consequence of the target outcome, unavailable at the decision time.'],
 ['A test set is safe because labels were hidden, even though features were selected using all labels. What is wrong?','Feature selection already used test outcomes; evaluation is contaminated.'],
 ['How does legitimate historical information differ from look-ahead leakage?','Historical information was available before prediction; look-ahead information comes from the future or target outcome.'],
 ['Before trusting an extraordinary backtest, what timestamp audit is needed?','When each input was actually available, including reporting delays and later data revisions.'],
 ['A scaler is fitted before the train/test split. What safer procedure should replace it?','Split first, fit the scaler on training data only, and apply that fitted transform to held-out data.'],
 ['Why can duplicate customers in training and test inflate a new-customer score?','The model can exploit customer-specific information it would not have for genuinely new customers.']],{prerequisites:['model-cross-validation'],sourceIds:['qres-leakage']}),
 r(8,'models','model-time-validation','Deployment validity','Temporal validation',
 'Evaluating predictions on later data while fitting only on earlier available data.',
 'It better matches forecasting and highlights changes over time.',
 'Use appropriate walk-forward splits, availability timestamps and gaps for overlapping or delayed outcomes.',
 'You must forecast tomorrow with today’s newspaper, not a newspaper printed tomorrow.',[
 ['Training uses January–June and testing uses July. What temporal boundary is respected?','Training uses earlier data than the test period, assuming features were available in time.'],
 ['Randomly splitting overlapping five-day return labels guarantees honest forecasting. What is wrong?','Training and test may share future outcome periods, leaking related information.'],
 ['How does an expanding-window split differ from a rolling-window split?','Expanding keeps all past training data; rolling keeps only a recent fixed-length history.'],
 ['Before comparing fold scores across time, what regime issue matters?','Market or user behavior may change; report time-specific performance rather than hiding it in one average.'],
 ['A target is known only 10 days after prediction. What should a live-like training split ensure?','Training labels are fully available before the test decision time; impose suitable timing boundaries or gaps.'],
 ['Why does a clean historical time split still not guarantee future performance?','Future distributions, liquidity, behavior or relationships can change.']],{prerequisites:['model-leakage'],sourceIds:['qres-timecv','qres-splits']}),
 r(8,'product','product-sequential','Product experiments','Planned sequential testing',
 'A testing method designed to allow valid repeated monitoring and stopping decisions.',
 'It permits early decisions while controlling the intended error criterion under its assumptions.',
 'Use a specified sequential design, alpha-spending rule or anytime-valid procedure rather than ordinary repeated fixed-sample tests.',
 'A race can have planned checkpoints with their own rules instead of declaring a winner whenever a runner briefly leads.',[
 ['A team wants to check results daily and stop early for benefit. What statistical design should it plan?','A valid sequential monitoring procedure with suitable decision thresholds and assumptions.'],
 ['Replacing every daily threshold with p < 0.05 solves optional stopping. What is wrong?','That repeats the same fixed-sample mistake; the full monitoring rule must be calibrated.'],
 ['How does a confidence sequence differ from an ordinary fixed-time confidence interval?','It is designed for simultaneous coverage across its permitted monitoring times, under the stated assumptions.'],
 ['Before using an anytime-valid method, what should match the experiment?','Its data, dependence, randomization, outcome and stopping assumptions.'],
 ['A test stops early for severe harm but no benefit claim is made. What should be documented?','The stopping trigger, timing, observed harms and the method used for any reported uncertainty.'],
 ['Why should sequential significance still be combined with a minimum useful lift?','A valid discovery can still be economically trivial or fail a guardrail.']],{prerequisites:['product-power','paper-optional-stopping'],sourceIds:['qres-sequential','qres-guardrails']}),
 r(8,'information','info-calibration','Forecast quality','Probability calibration',
 'Predicted probabilities matching event frequencies across suitable sets of comparable predictions.',
 'It makes forecast probabilities useful for risk-sensitive decisions.',
 'Check reliability across probability ranges on relevant held-out data, with uncertainty.',
 'Among many events labeled 80%, a calibrated forecast expects about 8 successes per 10, not success every time.',[
 ['A model labels 1,000 events as 80% likely; only 600 occur. What is the observed calibration gap?','Observed frequency is 60%, so the forecast overstates it by 20 percentage points.'],
 ['A classifier has 95% label accuracy, so its probabilities must be calibrated. What is wrong?','Accuracy checks chosen labels; probability calibration is a separate property.'],
 ['How does calibration differ from discrimination?','Calibration checks probabilities against frequencies; discrimination checks how well predictions separate outcomes.'],
 ['Before adjusting calibration, what evaluation separation is needed?','Use data for fitting the adjustment that are separate from the final evaluation, and relevant to deployment.'],
 ['For an event that occurs, what is binary Brier loss at predicted p = 0.8?','(0.8 − 1)² = 0.04. This single loss does not establish calibration.'],
 ['Why does lower Brier score not alone prove better calibration?','Brier score mixes calibration, discrimination and outcome uncertainty; inspect a suitable reliability analysis too.']],{prerequisites:['info-cross-entropy','model-logistic'],formula:'binary Brier loss = (p − y)²',sourceIds:['qres-calibration'],checks:[{expression:'80-600/1000*100',value:20},{expression:'(0.8-1)**2',value:0.04}]})
);

skills.push(
 // Band 9: choosing the estimand and stress-testing the evidence.
 r(9,'papers','paper-transport','External validity','Transporting an effect',
 'Applying an effect estimate to a new population or operating setting.',
 'It tests whether good evidence answers the decision actually faced.',
 'Compare effect modifiers, intervention delivery, outcomes and setting; justify any reweighting or extrapolation.',
 'A seed that grows in one climate may need different conditions in another.',[
 ['Young users gain 10 units and older users gain 2. A trial is 80% young. What average effect does that mix imply?','0.8 × 10 + 0.2 × 2 = 8.4 units, assuming the subgroup effects are valid.'],
 ['A randomized trial is internally valid, so its average applies everywhere. What is wrong?','A new population, setting or delivery method can have different effects.'],
 ['Using those subgroup effects, what average applies to a target that is only 20% young?','0.2 × 10 + 0.8 × 2 = 3.6 units; composition alone changes the average.'],
 ['Before reweighting trial participants to a target population, what support check matters?','Relevant target types must be represented, and required effect-modifier and selection assumptions must be credible.'],
 ['A strategy works in liquid large stocks. What must be checked before using it in small illiquid stocks?','Costs, execution, volatility, market structure and whether the underlying relationship persists.'],
 ['Why can matching age distributions be insufficient for transporting a treatment effect?','Other effect modifiers, delivery, baseline risks or measurement differences may remain.']],{prerequisites:['paper-selection','paper-heterogeneity'],sourceIds:['qres-external','qres-whatif'],checks:[{expression:'0.8*10+0.2*2',value:8.4},{expression:'0.2*10+0.8*2',value:3.6}]}),
 r(9,'papers','paper-estimand','Causal targets','A clearly defined estimand',
 'The precise quantity a study aims to estimate.',
 'It keeps different causal questions from being treated as the same answer.',
 'Specify population, intervention and comparator, outcome, time horizon, handling of intervening events and summary.',
 'A map needs a destination; a statistical method needs a clearly named target.',[
 ['A study asks about offering a program regardless of uptake. What assignment-based effect is relevant?','The effect of assignment or offer under the defined policy, commonly analyzed by original randomized group.'],
 ['Comparing only adherent participants automatically estimates what would happen if everyone adhered. What is wrong?','Adherence is post-assignment and can be related to prognosis; selection can bias the comparison.'],
 ['How does an offer effect differ from an effect if everyone actually used the program?','They involve different interventions and targets; non-uptake can make their magnitudes differ.'],
 ['Before interpreting \"treatment effect\", what event-handling question should be checked?','How switching, discontinuation, rescue treatment or missing outcomes fit the intended estimand.'],
 ['A subscription test offers discounts but some users never see them. What two questions should be separated?','The effect of the offer policy and the effect of actually receiving or viewing a discount.'],
 ['Why does changing from a treatment-policy to a hypothetical no-discontinuation analysis need explanation?','It changes the target effect and assumptions, not merely the statistical software.']],{prerequisites:['paper-instrument','paper-mediation'],sourceIds:['qres-estimands','qres-whatif']}),
 r(9,'papers','paper-sensitivity','Robust evidence','Sensitivity analysis',
 'Checking how conclusions change under plausible alternative assumptions or analysis choices.',
 'It shows whether a decision rests on a fragile modeling or missing-data assumption.',
 'Target the same estimand, vary justified assumptions and report the full range of relevant results.',
 'A bridge should be checked under several realistic loads, not only the load at which it looks strongest.',[
 ['An effect is +3 under missing-at-random but −1 under a plausible missing-outcome scenario. What does this show?','The conclusion is sensitive to the missing-data assumption; the sign is not robust across those scenarios.'],
 ['Trying many models and reporting the largest effect is sensitivity analysis. What is wrong?','That is selective search; sensitivity analysis transparently reports justified alternatives.'],
 ['How does sensitivity analysis differ from an independent replication?','It probes assumptions on existing evidence; replication adds new observations.'],
 ['Before presenting a reassuring robustness table, what choice issue should be checked?','Whether important plausible unfavorable assumptions were included, not only harmless variations.'],
 ['A strategy’s estimated profit is €400 before €100–€600 plausible extra execution costs. What net range follows?','€300 to −€200; execution-cost uncertainty can reverse profitability.'],
 ['Why must a sensitivity analysis keep its causal target clear?','Changing the population, treatment or outcome may answer a different question rather than test robustness of the same answer.']],{prerequisites:['paper-estimand','paper-attrition','paper-confounding'],sourceIds:['qres-estimands'],checks:[{expression:'400-100',value:300},{expression:'400-600',value:-200}]}),
 r(9,'papers','paper-clusters','Study dependence','Clustered observations',
 'Observations sharing a group can be correlated rather than independent.',
 'It prevents inflated precision from treating many related people or events as independent evidence.',
 'Align analysis with randomization and dependence; equal-cluster design effect is 1 + (m − 1)ρ.',
 'Forty people in one clinic can share staff and practices; they are not forty unrelated settings.',[
 ['Equal clusters contain 40 people with ICC 0.10. What is the simple design effect?','1 + (40 − 1) × 0.10 = 4.9, under the equal-cluster approximation.'],
 ['A trial randomizes 10 clinics but has 400 patients, so it has 400 independent assignments. What is wrong?','Assignment occurs at clinic level; within-clinic correlation must be handled.'],
 ['With 400 people and design effect 4.9, what rough effective size does the simple variance approximation suggest?','400 / 4.9 ≈ 81.6 independent-person equivalents, not 81.6 actual participants.'],
 ['Before using ordinary standard errors in a cluster trial, what must be checked?','The clustering level, number of clusters and a method valid for the dependence and small-cluster setting.'],
 ['A product test randomizes households but analyzes individuals independently. What may happen?','Correlated household outcomes can make ordinary intervals too narrow and evidence look stronger than it is.'],
 ['Why can adding many people to the same few clusters give diminishing information?','Shared cluster variation remains; new independent clusters can add more information than more highly related people.']],{prerequisites:['paper-randomization','paper-ci-reading'],sourceIds:['qres-cluster'],formula:'DE = 1 + (m − 1)ρ; rough neff = n / DE',checks:[{expression:'1+(40-1)*0.1',value:4.9},{expression:'400/(1+(40-1)*0.1)',value:81.63265306122449}]}),
 r(9,'papers','paper-protocol-integrity','Transparent research','Protocol changes and analysis integrity',
 'Keeping a traceable record of what was planned, changed and actually analyzed.',
 'It makes legitimate adaptation distinguishable from hidden result-driven selection.',
 'Document timing, reasons and impact of changes; retain the original target and label new targets clearly.',
 'Changing a game’s rules can be reasonable, but everyone must know when and why the change happened.',[
 ['A laboratory replaces a broken instrument before viewing outcomes and reports it. What should be assessed?','Whether the replacement affects comparability and the estimand; transparent changes are not automatically misconduct.'],
 ['A timestamped plan exists, so undisclosed later changes cannot matter. What is wrong?','The final analysis may deviate materially from the plan; compare both documents.'],
 ['How does a blinded design amendment differ from a result-driven outcome switch?','The blinded amendment can be made without seeing comparative results; a result-driven switch selects using outcomes.'],
 ['A final sample excludes 30% of participants not mentioned in the plan. What should be checked?','Reasons, timing, group balance and sensitivity to inclusion, especially whether exclusions depended on outcomes.'],
 ['A primary endpoint is inconclusive but one of 20 new subgroups looks positive. How should the subgroup be framed?','As exploratory unless a valid prospective plan and multiplicity strategy support a confirmatory claim.'],
 ['Why publish the original plan alongside a revised plan?','Readers can assess target changes, analytical flexibility and whether the evidence is being presented honestly.']],{prerequisites:['paper-preregistration','paper-primary-outcome','paper-phacking'],sourceIds:['qres-consort','qres-preregister']}),
 r(9,'models','model-causal-coefficient','Model interpretation','Prediction coefficients versus causal effects',
 'A fitted coefficient is a model relationship; a causal effect concerns an intervention.',
 'It prevents a good prediction from being used as an unsupported action rule.',
 'A coefficient needs a justified identification strategy and estimand to receive a causal interpretation.',
 'Umbrella sales help predict rain; changing umbrella sales does not command the weather.',[
 ['A sales model finds stores with more employees sell more. Does the coefficient prove hiring raises sales by that amount?','No. Expected demand, location or store size can drive both staffing and sales.'],
 ['Controlling 100 variables guarantees an advertising coefficient is causal. What is wrong?','Confounders may be missing and some controls may be mediators or colliders.'],
 ['How does a predictive model of who buys differ from the effect of sending an offer?','The first predicts existing behavior; the second asks what sending the offer changes compared with not sending it.'],
 ['Before turning a coefficient into a policy forecast, what causal assumptions should be checked?','The intervention definition, adjustment strategy, selection, confounding and whether the fitted form answers the estimand.'],
 ['A randomized price test estimates a valid local demand response. What limits extrapolation to a price far outside the test?','Nonlinearity, changing customer composition and lack of support for the new price range.'],
 ['Why can a variable improve forecasts while worsening a causal adjustment?','It may carry outcome information but also be a collider or mediator that biases the intervention estimate.']],{prerequisites:['model-multiple-regression','paper-dag','paper-estimand'],sourceIds:['qres-whatif']}),
 r(9,'models','model-distribution-shift','Deployment validity','Distribution shift',
 'Deployment data having different statistical behavior from training or evaluation data.',
 'It explains why even honestly evaluated models can degrade after release.',
 'Monitor inputs, outcomes, calibration and decision costs; distinguish changed input mix from changed input–outcome relationships.',
 'A winter clothing forecast may not work unchanged when the season becomes summer.',[
 ['A model was trained mostly on desktop users but deployment is mostly mobile. What shift may occur?','The input distribution changes; performance can change even if conditional relationships remain stable.'],
 ['A historical test passed, so live calibration cannot change. What is wrong?','User behavior, baseline rates or relationships can shift after evaluation.'],
 ['How does covariate shift differ from conditional relationship shift?','Covariate shift changes P(X) while P(Y|X) stays fixed; conditional shift changes the outcome relationship given inputs.'],
 ['Before correcting shift with weights, what overlap issue should be checked?','The training data must support relevant deployment inputs; extreme or unsupported weights can make estimates unstable.'],
 ['A betting model learned pre-rule-change scoring probabilities. What should be reevaluated after the rule change?','The conditional scoring relationship, calibration and economic performance under the new rules.'],
 ['Why can retraining on more old data fail to solve a new regime problem?','Old data may reinforce the relationship that no longer holds; recent relevant evidence and changed features may be needed.']],{prerequisites:['model-time-validation','info-calibration','paper-transport'],sourceIds:['qres-shift','qres-splits']}),
 r(9,'product','product-srm','Experiment trustworthiness','Sample-ratio mismatch',
 'Observed assignment counts differing from the planned ratio more than expected by chance.',
 'It flags possible allocation, eligibility or logging faults before interpreting metric changes.',
 'Test against the configured ratio and investigate the cause; do not automatically repair it by reweighting.',
 'If a fair sorting machine keeps sending many more objects to one bin, inspect the machine before comparing the bins.',[
 ['A 50/50 test records 1,800 A users and 1,200 B users. What shares were observed?','60% and 40%, rather than the planned 50% each.'],
 ['Unexpected counts can be ignored if conversion is highly significant. What is wrong?','The same fault may distort which users or events enter each metric, invalidating the effect estimate.'],
 ['For those counts, what is the Pearson chi-square statistic against 1,500 expected in each group?','300² / 1,500 + (−300)² / 1,500 = 120, a strong mismatch signal under that count model.'],
 ['Before blaming random assignment, what logging issue should be checked?','Whether exposure, eligibility, joins or missing events were recorded differently across variants.'],
 ['B causes a crash before its exposure event is logged. Why might counts favor A?','B users can disappear from logged counts, and surviving B outcomes may be a selected subset.'],
 ['Why is forcing counts to 50/50 without finding the cause inadequate?','It can hide a measurement or selection problem without restoring a valid randomized comparison.']],{prerequisites:['product-ab-random','paper-selection','paper-protocol-integrity'],sourceIds:['qres-srm'],formula:'χ² = Σ(observed − expected)² / expected',checks:[{expression:'1800/3000*100',value:60},{expression:'300**2/1500+(-300)**2/1500',value:120}]}),
 r(9,'information','info-data-processing','Information limits','Data-processing inequality',
 'Processing a signal cannot create extra information about a target if it adds no new target information.',
 'It separates better presentation or learnability from actually observing new evidence.',
 'For a Markov chain X → Y → Z, I(X;Z) ≤ I(X;Y).',
 'Copying and enlarging a blurry photograph cannot recover facts that were never captured.',[
 ['A target has 1 bit of information in a raw signal. A summary uses only that signal. Can it contain 2 bits about the target?','No, under the Markov assumptions; processing alone cannot increase target mutual information.'],
 ['A model scores better after feature processing, so the processing created new facts about the target. What is wrong?','It may make existing information easier for that model to use without increasing mutual information.'],
 ['How does adding a new independent measurement differ from reformatting the old measurement?','The new measurement can add evidence; reformatting is processing of existing evidence.'],
 ['Before applying the inequality, what conditional-information assumption matters?','Z must depend on X only through Y in the stated chain; no extra target-related input may enter.'],
 ['A compression step discards a feature important for rare fraud. What should be assessed?','Whether target information and decision performance were lost, especially for costly rare cases.'],
 ['Why can a denoising system help a limited predictor without violating the inequality?','It can expose a useful representation of the original information while not adding information beyond its inputs.']],{prerequisites:['info-mutual-information','model-distribution-shift'],formula:'X → Y → Z implies I(X;Z) ≤ I(X;Y)',sourceIds:['qres-infotheory']}),

 // Band 10: combined professional judgment.
 r(10,'papers','paper-appraisal','Research judgment','Whole-study appraisal',
 'Judging a study by its question, design, estimates, assumptions and practical relevance together.',
 'It prevents a single impressive statistic from standing in for the whole argument.',
 'Trace the chain from target question to recruitment, assignment, measurement, analysis, uncertainty and decision.',
 'Checking only a car’s top speed misses its brakes, fuel costs and suitability for your road.',[
 ['A huge study reports p = 0.001 and a 0.01-point benefit on a 0–100 scale. What is the first practical question?','Whether 0.01 points is meaningful, with valid uncertainty, costs and measurement considered.'],
 ['A prestigious journal and small p-value make design review unnecessary. What is wrong?','Reputation and significance do not remove confounding, selection, missing data or measurement problems.'],
 ['Which matters more for a causal claim: larger observational N or a justified identification strategy?','Identification is necessary for the causal interpretation; larger N mainly improves precision under the design.'],
 ['A paper’s conclusion is stronger than its estimate and interval. What should be checked?','Whether the wording claims causation, certainty or generalization beyond what the design and uncertainty support.'],
 ['A study of volunteers uses self-reported outcomes and excludes many dropouts. What three concerns combine?','Selection, measurement bias and attrition; examine how each could affect the stated effect.'],
 ['Why should a reader distinguish \"an interesting result\" from \"enough evidence to act\"?','Action depends on consequences, uncertainty, relevant alternatives and the cost of being wrong.']],{prerequisites:['paper-estimand','paper-sensitivity','paper-protocol-integrity'],sourceIds:['qres-consort','qres-asa','qres-estimands']}),
 r(10,'papers','paper-conflicting-evidence','Research judgment','Reconciling different studies',
 'Comparing study results while accounting for precision, selection and genuine setting differences.',
 'It avoids treating every conflicting headline as equal evidence or proof of dishonesty.',
 'Compare estimands, designs, effect estimates, intervals and risks of bias before synthesizing.',
 'A blurry close-up and a sharp wide photograph can tell different parts of the same story.',[
 ['A 42-person study reports a large effect, while a 4,000-person replication reports a small precise effect. What should be considered?','Selection inflation, uncertainty, study quality and real setting differences; give relevant precise evidence appropriate weight.'],
 ['One result is significant and the other is not, so their effects differ significantly. What is wrong?','A difference in significance is not a test of the difference between effect estimates.'],
 ['An original CI is 2 to 14 and replication CI 0.7 to 1.3. What is reasonable to investigate?','Their estimates appear substantially different; examine heterogeneity, selection and a direct comparison rather than only p-value labels.'],
 ['Before calling a replication decisive, what comparability check matters?','Whether it tests the same population, intervention, outcome and conditions with adequate fidelity.'],
 ['Three independent precise replications show a smaller effect than a noisy original. What evidence-based adjustment is sensible?','Revise the expected effect toward the well-supported smaller magnitude, while assessing heterogeneity and bias.'],
 ['Why should a meta-analysis not simply average a biased original and clean replication equally?','Their precision and validity differ; weighting and sensitivity analysis should reflect the relevant evidence structure.']],{prerequisites:['paper-replication','paper-winners-curse','paper-heterogeneity','paper-inverse-variance'],sourceIds:['qres-replicate','qres-meta','qres-power']}),
 r(10,'papers','paper-benefit-harm','Research judgment','Absolute benefit–harm judgment',
 'Comparing expected benefits and harms on meaningful absolute scales over the same horizon.',
 'It makes relative-risk claims useful for real decisions.',
 'Calculate absolute event changes, assess severity and uncertainty, and keep the target population explicit.',
 'Saving ten small inconveniences is not automatically better than causing one severe injury.',[
 ['Benefit risk falls from 2% to 1%, while harm risk rises from 0.2% to 0.8%. Per 1,000, what event changes are expected?','10 fewer benefit-target events and 6 extra harm events, if the causal risks transport over the stated period.'],
 ['A 50% relative risk reduction always outweighs a 300% relative harm increase. What is wrong?','Baseline risks, absolute counts, severity and uncertainty are needed; relative percentages alone cannot rank the tradeoff.'],
 ['For those causal risks, what are NNT and NNH?','NNT = 1 / 0.01 = 100; NNH = 1 / 0.006 ≈ 167, rounded up, over the same horizon.'],
 ['Before applying a trial’s benefit–harm balance to one patient, what must be checked?','Relevant baseline risks, preferences, effect modifiers, time horizon and applicability of the evidence.'],
 ['Assume each prevented event is worth 100 units and each added harm costs 200. What is expected net value per 1,000?','10 × 100 − 6 × 200 = −200 value units under those explicit valuations.'],
 ['Why can two people rationally choose differently from the same evidence?','Their baseline risk, priorities and valuations of outcomes can differ, even with the same estimated causal effects.']],{prerequisites:['paper-absolute-relative','paper-transport','paper-appraisal'],sourceIds:['qres-meta','qres-estimands'],checks:[{expression:'(0.02-0.01)*1000',value:10},{expression:'(0.008-0.002)*1000',value:6},{expression:'1/(0.008-0.002)',value:166.66666666666666},{expression:'10*100-6*200',value:-200}]}),
 r(10,'papers','paper-evidence-updating','Research judgment','Updating a body of evidence',
 'Revising beliefs and decisions as relevant new independent evidence becomes available.',
 'It keeps one famous finding from becoming an unchangeable conclusion.',
 'Use a transparent update rule, assess quality and selection, and distinguish fresh data from reanalysis of old data.',
 'A weather forecast should change when a new storm measurement arrives, not only when an old report is repeated.',[
 ['A preregistered large trial contradicts several selected small studies. What should a review do?','Reevaluate the full evidence, bias and heterogeneity; do not dismiss the new trial merely because it conflicts with a familiar story.'],
 ['Every new publication counts as an independent confirmation. What is wrong?','Papers can reuse the same participants, outcomes or analysis pipelines.'],
 ['How does a new independent study differ from another commentary about an old result?','It adds observations that can test the claim; commentary can clarify but does not itself add independent outcome data.'],
 ['Before repeatedly declaring a cumulative meta-analysis significant, what monitoring issue should be checked?','Repeated result-based decisions and selection can affect error rates; consider a suitable planned updating procedure.'],
 ['A study register lists 12 completed trials, but the review includes 7. What update work is needed?','Resolve the missing 5 trials and their outcomes before treating the visible evidence as complete.'],
 ['Why can a rational conclusion remain uncertain after an update?','The remaining evidence may be biased, heterogeneous, incomplete or too imprecise for a strong decision.']],{prerequisites:['paper-systematic-review','paper-appraisal','paper-publication-bias'],sourceIds:['qres-missing','qres-meta','qres-sequential'],checks:[{expression:'12-7',value:5}]}),
 r(10,'papers','paper-independent-confirmation','Research judgment','Exploration followed by confirmation',
 'Using exploratory work to generate a specific prediction, then testing it on independent evidence.',
 'It turns a flexible discovery process into a claim that can fail a new test.',
 'Freeze the proposed prediction and analysis before accessing the confirming outcomes; report all planned results.',
 'Finding a route on a map is exploration; successfully traveling it later is a fresh test.',[
 ['A subgroup was selected after 50 analyses. How can it be tested credibly next?','Specify the subgroup hypothesis and interaction test, then use new data with appropriate power and multiplicity handling.'],
 ['Retesting the selected subgroup on the same dataset is independent confirmation. What is wrong?','The outcome data already helped select it; the same chance pattern remains.'],
 ['How does a specification-curve or multiverse analysis help without replacing replication?','It shows sensitivity across justified choices on existing data; replication adds independent evidence.'],
 ['Before accepting a confirmation claim, what data-access history should be checked?','Whether the confirming outcomes were untouched when the prediction and test were fixed.'],
 ['A model wins among 200 candidates, then loses its edge on untouched future data. What did the new test reveal?','The selected historical advantage did not generalize under that evaluation; selection or regime change may explain it.'],
 ['Why should a failed confirmation still be reported?','It informs the evidence and limits publication bias; hiding it recreates selective visibility.']],{prerequisites:['paper-harking','paper-phacking','paper-sensitivity','paper-replication'],sourceIds:['qres-preregister','qres-flex','qres-replicate']}),
 r(10,'models','model-nested-validation','Professional validation','Nested model evaluation',
 'Separating model tuning from the evaluation of the whole tuning procedure.',
 'It reduces optimistic performance estimates caused by selecting the best model on evaluation data.',
 'Tune only inside each outer training split; evaluate once on its untouched outer test split using appropriate grouped or temporal boundaries.',
 'Choosing the fastest runner on one track and judging that choice on a different track tests the selection process, not just practice.',[
 ['Five outer folds each tune 10 settings with four inner folds. How many inner candidate fits occur?','5 × 10 × 4 = 200, excluding selected-model refits and any final full-data fit.'],
 ['The best inner-validation score is an unbiased final performance estimate. What is wrong?','That score helped select the model; outer held-out evaluation is needed for the selected procedure.'],
 ['How does an untouched final test set differ from an inner validation set?','The final test assesses a frozen choice; inner validation participates in tuning.'],
 ['In a forecast task, what extra rule must both nested levels respect?','Training must not use future data, leaked labels or improperly overlapping observations.'],
 ['A team revises features after each final-test result. What happens to that test?','It becomes part of development and can wear out as an independent evaluation; fresh relevant data may be needed.'],
 ['Why does nested validation still not guarantee useful live decisions?','Deployment shift, costs, calibration and target mismatch can remain even after honest model selection.']],{prerequisites:['model-cross-validation','model-regularization','model-time-validation','model-distribution-shift'],sourceIds:['qres-nested','qres-selection-models'],checks:[{expression:'5*10*4',value:200}]}),
 r(10,'models','model-decision-utility','Professional prediction','Prediction quality versus decision value',
 'A useful model must improve the decisions made with its predictions, not merely a generic score.',
 'It connects calibrated probabilities to benefits, costs and the option to take no action.',
 'Compare expected utility for available actions using relevant probabilities and costs; validate the entire decision rule.',
 'A weather forecast matters differently to someone carrying an umbrella and someone scheduling an outdoor event.',[
 ['An action earns €30 if successful and loses €70 otherwise. At p = 75%, what is expected net payoff?','0.75 × €30 − 0.25 × €70 = €5 before extra costs.'],
 ['A classifier with the highest accuracy must create the most profit. What is wrong?','Error costs, baseline rates, probability calibration and action thresholds can differ.'],
 ['For the €30 gain and €70 loss, what break-even success probability is needed?','30p − 70(1 − p) = 0 gives p = 70%; require more than 70% for positive payoff before costs.'],
 ['Before using a model probability for sizing or commitment, what uncertainty must be checked?','Calibration, estimation error, dependence, shift and whether costs are accurately measured.'],
 ['A supposedly 75% chance is actually 65%. What is the same action’s true expected payoff?','0.65 × €30 − 0.35 × €70 = −€5; probability error reverses the decision.'],
 ['Why might a modestly accurate transparent model outperform a more complex one economically?','It may be better calibrated, cheaper, more stable or better aligned with costly decision errors.']],{prerequisites:['model-logistic','info-calibration','model-nested-validation'],formula:'EV(action) = p × gain − (1 − p) × loss − costs',sourceIds:['qres-calibration','qres-splits'],checks:[{expression:'0.75*30-0.25*70',value:5},{expression:'70/(30+70)',value:0.7},{expression:'0.65*30-0.35*70',value:-5}]}),
 r(10,'product','product-rollout-judgment','Product judgment','Evidence-based product rollout',
 'Choosing whether to release a change using valid causal evidence, meaningful effects and net consequences.',
 'It prevents shipping a statistically attractive but economically harmful feature.',
 'Check allocation and measurement, planned metrics, uncertainty, guardrails, unit economics and transport to rollout.',
 'A test drive should assess handling, safety and cost, not just whether the engine briefly revved higher.',[
 ['Estimated conversion lift is 0.2 percentage points for 10,000 users. With €25 contribution per extra sale, what benefit is projected?','0.002 × 10,000 = 20 extra sales; 20 × €25 = €500 if the effect and margin hold.'],
 ['A positive p-value result alone is enough to ship worldwide. What is wrong?','The result may be practically small, harmed by selection, fail guardrails or not transport to all users.'],
 ['That projected benefit is €500 per period and operating cost is €800. What is estimated net value?','€500 − €800 = −€300 per period before further uncertainty and side effects.'],
 ['Before trusting a segmented rollout gain, what analysis issue should be checked?','Whether the segment was planned, sufficiently precise and tested for an actual interaction rather than chosen after a search.'],
 ['A positive test shows sample-ratio mismatch and changed logging. What should happen before interpreting the gain?','Diagnose and fix the data-quality issues; the measured gain may not represent a valid randomized effect.'],
 ['Why can gradual rollout with continued monitoring be preferable after a promising valid test?','It can detect deployment shifts, long-run harms and rare failures while limiting exposure, using suitable monitoring rules.']],{prerequisites:['product-srm','product-sequential','product-unit-economics','paper-transport'],sourceIds:['qres-srm','qres-guardrails','qres-exp'],checks:[{expression:'0.002*10000',value:20},{expression:'0.002*10000*25',value:500},{expression:'500-800',value:-300}]}),
 r(10,'information','info-information-value','Information judgment','Information gain and decision value',
 'Information gain measures a change in probabilistic knowledge; decision value measures the payoff improvement it enables.',
 'It stops surprising news or lower prediction loss from being confused with a profitable decision.',
 'Expected information gain is expected posterior-to-prior KL; value of information compares optimal expected action payoffs before and after learning.',
 'Learning the color of a hidden card can be informative yet worthless if the game pays the same for every color.',[
 ['A fair binary uncertainty has entropy 1 bit. After a clue, probabilities are 90%/10%. What is the entropy?','−0.9 log₂0.9 − 0.1 log₂0.1 ≈ 0.469 bits for that posterior.'],
 ['Every observation must lower entropy for the particular realized posterior. What is wrong?','A surprising observation can raise posterior uncertainty; expected information gain averages over possible observations.'],
 ['If a signal changes beliefs but cannot change any available action payoff, what is its decision value?','Zero under those decision assumptions, despite possibly positive information gain.'],
 ['Before paying for information, what should be checked besides accuracy?','Whether it arrives in time, changes a decision, improves expected payoff and costs less than that improvement.'],
 ['A signal raises optimal expected payoff from €8 to €12 and costs €6. What is its net value?','€12 − €8 − €6 = −€2; informative does not mean worth buying.'],
 ['Why can more data have diminishing decision value?','Once the best action is already clear, extra precision may rarely change the choice or payoff.']],{prerequisites:['info-kl','info-mutual-information','model-decision-utility'],formula:'expected information gain = E[D_KL(posterior || prior)]; net VOI = expected payoff gain − information cost',sourceIds:['qres-infotheory'],checks:[{expression:'-0.9*Math.log2(0.9)-0.1*Math.log2(0.1)',value:0.4689955935892812},{expression:'12-8-6',value:-2}]})
);

export default skills;
